INSERT INTO "modulo" ("numero","titulo","icono") VALUES(2,'Fundamentos de Desarrollo Front-End','devices');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(3,'Fundamentos de Programacion en JavaScript','data-object');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(4,'Programacion Avanzada en JavaScript','bolt');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(5,'Fundamentos de Bases de Datos Relacionales','database');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(6,'Desarrollo de Aplicaciones Web Node Express','dns');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(7,'Acceso a Datos en Aplicaciones Node','layers');
INSERT INTO "modulo" ("numero","titulo","icono") VALUES(8,'Implementacion de API Backend Node Express','shield-lock');
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(1,2,'json_2026',1,'¿Qué limita estrictamente al Front-End en comparación con el Back-End en la arquitectura web?','El Front-End corre dentro del navegador, y el navegador no le da acceso al sistema de archivos del servidor: esa es una frontera de seguridad, no una limitación de las herramientas. Las otras tres describen cosas que el Front-End sí hace (estilos dinámicos) o que simplemente no son ciertas (ningún framework es obligatorio).',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(2,2,'json_2026',2,'¿Cuál es el rol fundamental del protocolo HTTP en la comunicación entre capas de desarrollo web?','HTTP es un protocolo sin estado: cada petición llega sin memoria de las anteriores, y por eso las sesiones hay que construirlas encima con cookies o tokens. Las otras tres atribuyen a HTTP trabajos que hacen CSS, el compilador o la base de datos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(3,2,'json_2026',3,'En una arquitectura Fullstack clásica, ¿qué componente intermedio separa la lógica Front y Back?','La API es el contrato entre las dos capas: el Front-End pide y recibe datos sin saber cómo están guardados, y el Back-End los entrega sin saber cómo se van a dibujar. Esa separación es lo que permite cambiar un lado sin tocar el otro.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(4,2,'json_2026',4,'¿Para qué usaría primariamente el inspector del navegador un desarrollador Front-End al depurar?','El inspector sirve para las dos cosas a la vez: editar el DOM en vivo para probar un cambio sin recompilar, y mirar la pestaña de red para ver qué peticiones salieron y qué respondieron. Las otras tres describen tareas de servidor o de compilación, que no ocurren en el navegador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(5,2,'json_2026',5,'Según la tríada de desarrollo web, ¿qué rol técnico fundamental asume JavaScript en cliente?','En la tríada, HTML pone la estructura, CSS la presentación y JavaScript el comportamiento: es el único de los tres que puede reaccionar a un evento y modificar el DOM después de que la página cargó. Las alternativas (a) y (b) describen justamente a HTML y a CSS.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(6,2,'json_2026',6,'En un formulario HTML5, ¿qué atributo del form define la URI destino al procesar datos enviados?','`action` es el atributo que dice a qué URI se envían los datos del formulario. `enctype` define cómo se codifican, `target` dónde se abre la respuesta, y `rel` ni siquiera pertenece a `<form>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(7,2,'json_2026',7,'¿Cuál es la función semántica estricta de la etiqueta `<aside>` según los estándares de HTML5?','`<aside>` es para contenido relacionado con el principal pero que puede separarse de él sin que el texto pierda sentido: una barra lateral, una nota al margen, un bloque de enlaces relacionados. Si el contenido fuera indispensable para entender la página, no iría en un `<aside>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(8,2,'json_2026',8,'¿Qué combinación de etiquetas HTML5 es correcta para instanciar un menú de opciones nativo?','El menú desplegable nativo de HTML es un `<select>` que contiene elementos `<option>`. Las otras tres combinan etiquetas que no existen en el estándar: `<dropdown>`, `<item>` y `<list>` son inventadas, y `<datalist>` existe pero acompaña a un `<input>`, no reemplaza al `<select>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(9,2,'json_2026',9,'¿Dónde deben declararse semánticamente los links a hojas de estilos externas y metadatos vitales?','El `<head>` es donde va todo lo que describe el documento sin dibujarse: hojas de estilo, metadatos, título. Poner ahí la hoja de estilos permite además que el navegador empiece a pedirla antes de encontrarse con el contenido. La alternativa (b) es el error clásico de confundirla con los scripts, que sí se ponen al final del `<body>` y por un motivo distinto: no bloquear el dibujado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(10,2,'json_2026',10,'Para lograr accesibilidad, ¿qué etiqueta asocia lógicamente grupos de controles de formulario?','`<fieldset>` agrupa controles relacionados y, junto con `<legend>`, hace que un lector de pantalla anuncie a qué grupo pertenece cada campo. Las alternativas (a) y (c) son etiquetas inventadas, y (d) es un `<div>` con un rol ARIA: parcha la accesibilidad en vez de usar la etiqueta que ya existe para eso.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(11,2,'json_2026',11,'¿Qué atributo HTML asegura vincular explícita y unívocamente una etiqueta `<label>` con un input?','El atributo `for` del `<label>` apunta al `id` del campo, y ese vínculo hace dos cosas: el lector de pantalla anuncia la etiqueta al enfocar el campo, y hacer clic en el texto pone el cursor dentro. `name` sirve para enviar el dato, no para vincular.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(12,2,'json_2026',12,'En el modelo de cajas CSS, ¿qué propiedad añade espacio transparente externo perimetral al borde?','En el modelo de cajas, de adentro hacia afuera van contenido, `padding`, `border` y `margin`. El `margin` es el espacio exterior al borde, y es transparente: separa la caja de sus vecinas. El `padding` es el espacio interior, entre el contenido y el borde.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(13,2,'json_2026',13,'Según el cálculo de especificidad CSS, ¿cuál de los siguientes selectores prevalece en conflicto?','La especificidad se cuenta por categorías, y un identificador pesa más que cualquier cantidad de clases o elementos. Sólo (c) tiene un `#id`, así que gana sin necesidad de contar el resto: (a) suma dos clases, (b) una clase y cuatro elementos, y (d) sólo elementos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(14,2,'json_2026',14,'¿Qué atajo media query CSS restringe la regla exclusivamente a Viewports de mínimo 1024px?','`min-width` significa «desde este ancho hacia arriba», así que la regla se aplica a viewports de 1024px o más. La (a) hace justo lo contrario con `max-width`, y las otras dos usan sintaxis que no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(15,2,'json_2026',15,'¿Qué declaración box-sizing engloba el padding y el border en el cálculo del width total asignado?','Con `border-box`, el `width` que declaras es el ancho final de la caja: el `padding` y el `border` se descuentan hacia adentro en vez de sumarse. Con `content-box`, que es el valor por omisión, el `width` describe sólo el contenido y todo lo demás se suma encima.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(16,2,'json_2026',16,'Ante la colisión de estilos de distintos orígenes, y sin usar `!important`, ¿qué estilo CSS impone mayor prioridad?','En la cascada, un estilo puesto en el atributo `style` del elemento pesa más que cualquier regla de una hoja de estilos, venga de un archivo externo o de un `<style>` embebido. La alternativa (d) es el distractor que más enseña: el orden de los orígenes es navegador, luego usuario, luego autor, así que la hoja del usuario queda por debajo. Sólo se invierte con `!important`, y por eso el enunciado lo descarta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(17,2,'json_2026',17,'¿Qué operador relacional CSS filtra afectando solo a los descendientes de primer grado (hijos)?','El signo `>` es el combinador de hijo directo: `div > p` afecta a los párrafos que cuelgan inmediatamente del `div`, no a los que están más abajo. El espacio alcanza a todos los descendientes, `+` al hermano inmediato y `~` a los hermanos siguientes.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(18,2,'json_2026',18,'¿Cuántas fracciones equitativas articulan como límite la arquitectura del grid de Bootstrap?','La grilla de Bootstrap divide cada fila en 12 columnas, y 12 se eligió porque se reparte en mitades, tercios, cuartos y sextos sin decimales. Por eso las clases van de `col-1` a `col-12` y la suma dentro de una fila debería dar 12.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(19,2,'json_2026',19,'¿Qué sufijo responsivo activa modificaciones de diseño en Bootstrap al superar el breakpoint grande?','El sufijo `lg` corresponde al breakpoint «grande», que en Bootstrap arranca en 992px. Los sufijos van de menor a mayor —`sm`, `md`, `lg`, `xl`— y cada uno aplica desde su ancho hacia arriba, no sólo dentro de un tramo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(20,2,'json_2026',20,'¿Qué clase central de Bootstrap estabiliza el margen limitando y centrando el ancho del contenido?','`.container` fija un ancho máximo por cada breakpoint y centra el bloque con márgenes automáticos. `.container-fluid` hace lo contrario: ocupa siempre el 100% del ancho disponible. Las otras dos clases no existen en Bootstrap.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(21,2,'json_2026',21,'En el sistema de utilidades, ¿qué clase induce a un nodo tipo block a ocupar el 100% de su padre?','`.w-100` es la utilidad de ancho que fija `width: 100%`, de modo que el elemento ocupa todo el ancho de su contenedor padre. Las otras tres no existen en Bootstrap.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(22,2,'json_2026',22,'En Bootstrap 4, ¿qué propósito de interfaz cumple el componente jumbotron?','El jumbotron es un bloque destacado, con fondo y espaciado generosos, para resaltar el mensaje principal al comienzo de una página. El enunciado dice «en Bootstrap 4» a propósito: en Bootstrap 5 el componente se eliminó y su efecto se reconstruye combinando utilidades de fondo, borde y espaciado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(23,2,'json_2026',23,'¿Bajo qué doctrina base se estructura algorítmicamente el flujo responsivo en Bootstrap por defecto?','Bootstrap está construido «mobile first»: los estilos base valen para pantallas chicas y las media queries usan `min-width` para ir agregando reglas hacia arriba. Por eso una clase sin sufijo, como `.col-6`, aplica desde el móvil en adelante.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(24,2,'json_2026',24,'En evaluación nativa de JavaScript, ¿qué método atrapa de forma veloz a un único nodo por su ID?','`getElementById()` va directo al índice interno de identificadores del documento, así que devuelve el nodo sin recorrer el árbol. `querySelector("[id]")` sí recorre y además devolvería el primer elemento que tenga cualquier `id`, no el que buscas; y `document.findAll()` no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(25,2,'json_2026',25,'A nivel de memoria y asignación, ¿por qué es crítico utilizar "let" sobre "var" al iterar ciclos?','`var` se declara a nivel de función, así que en un bucle todas las vueltas comparten la misma variable, y una función definida dentro del ciclo termina viendo el último valor. `let` crea una variable nueva por cada iteración del bloque, y cada cierre captura la suya.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(26,2,'json_2026',26,'¿Qué detonante de evento del DOM percibe mutaciones confirmadas cuando el elemento pierde el foco?','`change` se dispara cuando el campo pierde el foco **y además** su valor cambió respecto de cuando lo ganó: por eso el enunciado dice «mutaciones confirmadas». `input` se dispara con cada tecla, sin esperar a que el campo se abandone.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(27,2,'json_2026',27,'Considerando la sintaxis funcional ES6, ¿qué sentencia declara una arrow function correctamente?','La sintaxis de una arrow function es lista de parámetros, flecha y cuerpo: `() => {}`. La (a) mezcla `function` con la flecha, que no se combinan; las otras dos no son sintaxis válida.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(28,2,'json_2026',28,'Si intentas reasignar una variable declarada con `const`, ¿qué ocurre en tiempo de ejecución?','Reasignar una variable declarada con `const` lanza un `TypeError` y corta la ejecución: el enlace entre el nombre y su valor es lo que `const` congela. Conviene no confundirlo con lo otro: si la constante apunta a un objeto o a un arreglo, **modificar su contenido está permitido** y no lanza nada. `const` protege la referencia, no lo referenciado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(29,2,'json_2026',29,'Durante la fase de coerción implícita, ¿qué entrega la ejecución de la sentencia binaria "3" + 3?','Con el operador `+`, si uno de los operandos es una cadena, JavaScript convierte el otro a cadena y concatena: `"3" + 3` da `"33"`, del tipo String. Es el `+` el que se comporta así; con `-`, `*` o `/` la conversión va hacia número y `"3" - 3` daría `0`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(30,2,'json_2026',30,'Al cargar jQuery, ¿qué símbolo queda definido como atajo de la función `jQuery`?','jQuery define la variable global `$` como atajo de la función `jQuery`, y por eso todo el código de la librería empieza con ese símbolo. Son la misma función con dos nombres: `$("#x")` y `jQuery("#x")` hacen lo mismo. Y como `$` es una variable corriente, se puede soltar con `jQuery.noConflict()` cuando otra librería la reclama.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(31,2,'json_2026',31,'¿Cuál es el patrón estandarizado para adjuntar manejadores "click" en nodos asíncronos vía jQuery?','`.on("click", ...)` es la forma vigente de asociar manejadores en jQuery, y es la que además permite delegar en un ancestro para que funcione con nodos que todavía no existen al momento de registrarla. `.bindClick()` y `.eventListener()` no existen, y la (b) dispara el clic en vez de escucharlo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(32,2,'json_2026',32,'¿Qué directriz bloquea la ejecución de scripts en jQuery hasta asegurar que el árbol DOM está listo?','`$(document).ready()` retrasa la ejecución hasta que el árbol DOM está construido, de modo que los selectores encuentren los elementos. Sin eso, un script en el `<head>` correría antes de que existieran los nodos que busca. Las otras tres no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(33,2,'json_2026',33,'Al parsear datos, ¿qué función encapsula jQuery para forzar la lectura del contenido de un `<input>`?','`.val()` lee y escribe el valor de los controles de formulario, que es donde vive el contenido de un `<input>`. `.text()` y `.html()` trabajan sobre el contenido entre etiquetas de apertura y cierre, y un `<input>` no tiene: es un elemento vacío.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(34,2,'json_2026',34,'¿Qué técnica animada nativa de jQuery altera gradualmente la opacidad hasta colapsar el nodo visual?','`.fadeOut()` baja la opacidad de forma gradual y, al terminar, oculta el elemento. `.hide()` lo esconde de golpe, `.slideUp()` lo colapsa por altura en vez de por opacidad, y `.collapse()` no es de jQuery sino de Bootstrap.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(35,2,'json_2026',35,'¿Qué mutación estructural consolida temporalmente ''git add'' en la topología de un flujo versionado?','`git add` mueve los cambios del directorio de trabajo al área de preparación, que es una zona intermedia donde se arma el próximo commit. No guarda nada en la historia todavía: eso lo hace `git commit`, que es la alternativa (b).',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(36,2,'json_2026',36,'Al gatillar ''git commit'' careciendo de archivos indexados previos, ¿qué respuesta retorna Git CLI?','Sin nada en el área de preparación no hay cambios que registrar, así que Git aborta e informa que no hay nada que confirmar. No inventa un commit vacío ni guarda el directorio de trabajo por su cuenta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(37,2,'json_2026',37,'Frente a múltiples vectores de desarrollo, ¿qué previene tácticamente el aislamiento en ramas (branch)?','Una rama aísla el trabajo en curso, de modo que el código a medio hacer no se mezcla con la línea principal hasta que alguien lo revise e integre. Las otras tres describen problemas de disco, de red o de criptografía, que no son lo que las ramas resuelven.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(38,2,'json_2026',39,'En presencia de un Merge Conflict grave, ¿qué protocolo manual asume irrevocablemente el usuario?','Ante un conflicto, Git marca las zonas en disputa dentro del archivo y se detiene: es la persona quien decide qué código queda y luego confirma la resolución con un commit. Las otras tres son maniobras para esquivar el conflicto, y todas pierden trabajo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(39,2,'json_2026',40,'¿Cuál es la disparidad motriz exacta entre invocar "git fetch" frente a procesar un "git pull"?','`git fetch` trae los commits del remoto y actualiza las ramas de seguimiento, sin tocar tu rama de trabajo: puedes mirar qué llegó antes de integrarlo. `git pull` hace ese mismo `fetch` y además lo fusiona en tu rama en el mismo acto.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(40,2,'js_2026',1,'¿Cuál es la principal responsabilidad arquitectónica del rol Front-End en una aplicación web moderna?','El rol Front-End se ocupa de lo que ocurre en el navegador: construir la interfaz y responder a lo que hace la persona. La lógica de negocio, la base de datos y la configuración del servidor pertenecen al Back-End o a operaciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(41,2,'js_2026',2,'¿Cuál selector CSS posee mayor especificidad entre un ID, una clase, un elemento y un pseudo-elemento?','En el cálculo de especificidad, los identificadores forman una categoría que pesa más que las clases, y las clases más que los elementos y pseudo-elementos. Un solo `#id` le gana a cualquier cantidad de clases.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(42,2,'js_2026',3,'¿Qué regla CSS se utiliza para aplicar estilos condicionales basados en el ancho de la pantalla?','`@media` es la regla que condiciona estilos a las características del dispositivo, y `max-width: 768px` los aplica desde ese ancho hacia abajo. Las otras tres son sintaxis inventada: no existen `@responsive`, `@viewport` con esa forma ni `@screen`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(43,2,'js_2026',4,'En el sistema de grillas de Bootstrap, ¿en cuántas columnas iguales se divide por defecto una fila?','Bootstrap divide cada fila en 12 columnas, número elegido por ser divisible en mitades, tercios, cuartos y sextos sin decimales.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(44,2,'js_2026',5,'¿Qué método nativo de JavaScript retorna el primer elemento que coincida con un selector CSS específico?','`querySelector()` acepta cualquier selector CSS y devuelve el primer elemento que coincida, o `null` si no hay ninguno. `querySelectorAll()` devuelve todos, y los dos `getElement...` sólo buscan por id o por clase, sin admitir selectores compuestos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(45,2,'js_2026',6,'¿Qué evento de JavaScript se dispara inmediatamente cuando un elemento HTML pierde el foco?','`blur` se dispara en cuanto el elemento pierde el foco, haya cambiado su valor o no. Es lo que lo separa de `change`, que además exige que el valor sea distinto del que tenía al recibir el foco.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(46,2,'js_2026',7,'¿Cuál es el ámbito (scope) de una variable declarada con la palabra clave let dentro de un bloque?','`let` tiene alcance de bloque: existe sólo entre las llaves donde se declaró, incluidas las de un `if` o un `for`. Es lo que la separa de `var`, que tiene alcance de función y se filtra fuera del bloque.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(47,2,'js_2026',8,'En jQuery, ¿qué método se utiliza para cambiar o extraer el contenido HTML interno de un elemento?','`.html()` lee o reemplaza el contenido HTML interno del elemento, interpretando las etiquetas. `.text()` hace lo mismo pero tratando todo como texto plano, y `.val()` trabaja sobre el valor de los controles de formulario.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(48,2,'js_2026',9,'¿Cómo se asocia un evento de clic a un botón utilizando la sintaxis estándar de la librería jQuery?','`$("button").click(function() { })` es el atajo de jQuery para registrar un manejador de clic. La (b) es JavaScript nativo y además está incompleta, y las otras dos usan métodos que jQuery no tiene.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(49,2,'js_2026',10,'¿Qué comando de Git registra oficialmente los cambios preparados (staging) en el repositorio local?','`git commit` toma lo que está en el área de preparación y lo registra en la historia del repositorio local. `git add` sólo prepara, `git push` envía al remoto lo ya confirmado, y `git status` no escribe nada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(50,2,'js_2026',11,'¿Qué comando de Git permite crear una nueva rama y cambiar a ella de manera simultánea?','Los dos comandos crean la rama y se cambian a ella en un solo paso: `git checkout -b` es la forma clásica y `git switch --create` la moderna, que Git introdujo justamente para separar el cambio de rama de la restauración de archivos. Por eso la respuesta correcta es la que las reconoce a ambas, y por eso esta pregunta no se puede barajar: su alternativa (d) nombra a las otras dos por su letra.',NULL,1,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(51,2,'js_2026',12,'En GitHub, ¿qué propósito principal cumple la creación de un Pull Request (PR)?','Un Pull Request propone integrar una rama en otra y abre el espacio donde se revisa y comenta el cambio antes de fusionarlo. Es una función de la plataforma, no de Git: sirve para que la integración pase por una revisión.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(52,2,'js_2026',13,'¿Qué sucede cuando Git detecta modificaciones concurrentes en la misma línea durante una unión?','Cuando dos ramas modifican la misma línea, Git no puede decidir cuál gana: marca el conflicto dentro del archivo y detiene la fusión hasta que alguien lo resuelva a mano. No sobrescribe ni descarta nada por su cuenta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-09',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(53,3,'json_2026',1,'¿Cuál es el motor principal que compila y ejecuta JavaScript dentro de Google Chrome?','V8 es el motor de JavaScript de Chrome, y también el que hace funcionar a Node.js. Las otras tres existen de verdad y por eso son buenos distractores: SpiderMonkey es el de Firefox, JavaScriptCore el de Safari, y ChakraCore el del Edge antiguo, el que había antes de que Edge pasara a construirse sobre Chromium y adoptara V8.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(54,3,'json_2026',2,'¿Qué limitación de seguridad crítica tiene JavaScript al ejecutarse nativamente en el navegador?','El navegador ejecuta el código dentro de una caja de arena, y esa caja no le da acceso al sistema de archivos del equipo. Es una frontera de seguridad deliberada, no una carencia del lenguaje. Las otras tres describen cosas que JavaScript sí hace todos los días: modificar el DOM, pedir datos con `fetch` y animar. Ojo con un matiz que conviene entender: sí se pueden leer archivos que el usuario elige a mano en un `<input type="file">`, porque ahí el permiso lo da una persona. Lo prohibido es entrar solo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(55,3,'json_2026',3,'¿Para qué se utiliza principalmente la consola de comandos de JavaScript en el navegador?','La consola sirve para mirar por dentro un programa que ya está corriendo: escribir expresiones y ver qué devuelven, leer los errores, inspeccionar valores. Las otras tres describen herramientas distintas: JavaScript no se compila a ensamblador a mano, la interfaz se diseña con HTML y CSS, y la conexión a la base de datos vive en el servidor y no en el navegador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(56,3,'json_2026',4,'En un entorno de navegador, ¿qué objeto global actúa como el contexto raíz de ejecución?','En el navegador, `window` es el objeto global: todo lo que se declara sin encerrar en un módulo o una función cuelga de ahí. `document` también es global, pero representa el documento y no el contexto raíz; `global` es el nombre que usa Node.js, no el navegador; y `navigator` describe el navegador y sus capacidades. Desde ES2020 existe además `globalThis`, que nombra el objeto global sea cual sea el entorno.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(57,3,'json_2026',5,'Al cargar un script en HTML, ¿qué atributo asegura que se ejecute tras parsear el documento?','`defer` le dice al navegador que descargue el script en paralelo pero que no lo ejecute hasta terminar de parsear el documento, y por eso el DOM ya está completo cuando el código corre. `async` también descarga en paralelo, pero ejecuta apenas termina la descarga, que puede ser en mitad del parseo; ese es justamente el par que hay que saber distinguir. `load` y `wait` no son atributos de `<script>`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(58,3,'json_2026',6,'¿Qué ocurre si un script con errores sintácticos severos se ejecuta en el navegador?','Un error de sintaxis se detecta al parsear, antes de ejecutar nada, así que ese script no llega a correr ni una sola línea y el motor informa un `SyntaxError` en la consola. Conviene precisar el alcance de esa detención: lo que no se ejecuta es **ese** script, mientras la página, los demás scripts y los manejadores de eventos siguen funcionando con normalidad. Ninguna de las otras tres ocurre: el navegador no corrige código, no recarga la página solo, y no puede saltarse la línea defectuosa porque no llegó a entender el archivo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(59,3,'json_2026',7,'¿Cuál es el principal beneficio de aislar el código JavaScript en un archivo externo .js?','Un archivo `.js` aparte lo pueden compartir varias páginas y el navegador lo guarda en caché, así que se descarga una vez y se reutiliza. Las otras tres prometen algo que no ocurre: separar el archivo no encripta nada, no obliga al servidor a procesarlo, y desde luego no impide descargarlo — cualquiera puede abrir la URL del archivo y leerlo entero.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(60,3,'json_2026',8,'Según las herramientas del browser, ¿qué pestaña permite analizar el rendimiento del script?','La pestaña «Performance» graba una línea de tiempo de lo que hizo la página: cuánto tardó cada función, dónde se fue el tiempo, qué bloqueó el dibujado. Las otras tres son pestañas reales con otro oficio: «Elements» inspecciona el DOM y los estilos, «Network» mira las peticiones y sus tiempos de red, y «Application» muestra almacenamiento, cookies y service workers.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(61,3,'json_2026',9,'¿Qué provoca declarar una variable sin usar let, const o var en modo no estricto?','En modo no estricto, asignar a un nombre que nunca se declaró crea una propiedad en el objeto global en vez de fallar. Es una de las razones de ser de `''use strict''`, que convierte ese descuido en un `ReferenceError`. Por eso la (a) no es correcta aquí: sí hay error, pero solo en modo estricto, que es justo lo que el enunciado descarta. Y no es local ni queda en `undefined`: queda global y con el valor asignado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(62,3,'json_2026',10,'Al evaluar la expresión `[] == false`, ¿qué resultado y por qué se produce en JavaScript?','El resultado es `true`, y la cadena de conversiones es lo que hay que entender: `false` se convierte al número `0`, y el arreglo vacío se convierte primero a la cadena `""` y de ahí al número `0`; `0 == 0` da verdadero. Lo que conviene fijar es que `==` compara convirtiendo a **número**, no a booleano. De ahí sale algo que parece contradictorio y no lo es: `[] == false` da `true` y al mismo tiempo `[] ? ''sí'' : ''no''` da `''sí''`, porque como condición un arreglo vacío es verdadero. Son dos reglas distintas —la de `==` y la de los valores truthy— y aplicarlas cruzadas es el error más común con este operador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(63,3,'json_2026',11,'¿Qué valor asume una variable declarada con `let` pero que carece de inicialización explícita?','Declarar sin asignar deja la variable en `undefined`, que es el valor que JavaScript usa para «existe pero todavía no tiene nada». `null` es distinto: significa «vacío a propósito» y hay que escribirlo. `NaN` aparece al fallar una operación numérica, y `0` habría que asignarlo. La distinción entre `undefined` y `null` es una de las que más se preguntan.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(64,3,'json_2026',12,'¿Qué operador lógico retorna el primer operando falso o el último verdadero si todos lo son?','`&&` va evaluando de izquierda a derecha y se detiene en el primer operando falso, devolviéndolo tal cual; si ninguno lo es, devuelve el último. Esa es la razón de que `&&` no devuelva siempre `true` o `false` sino uno de los operandos. `||` hace lo simétrico: primer verdadero o último. `!` niega y siempre da booleano, y `??` solo reacciona ante `null` y `undefined`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(65,3,'json_2026',13,'¿Cuál es la precedencia correcta, de mayor a menor, en los operadores aritméticos básicos?','Multiplicación y división se evalúan antes que suma y resta, igual que en aritmética, y los paréntesis siguen mandando sobre todo. Por eso `2 + 3 * 4` da 14 y no 20. La (a) y la (c) invierten el orden, y la (d) es lo que pasaría si no hubiera precedencia, que es exactamente lo que la precedencia existe para evitar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(66,3,'json_2026',14,'Si `a = 5` y evaluamos `b = a++`, ¿cuál es el valor final de `b` y `a` respectivamente?','El `++` puesto **después** de la variable devuelve el valor viejo y luego incrementa: `b` se queda con 5 y `a` pasa a 6. Si estuviera puesto antes, `b = ++a`, los dos valdrían 6, que es la alternativa (a). Esa diferencia entre postfijo y prefijo es todo lo que la pregunta evalúa, y es de las que se responden mal por leer rápido.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(67,3,'json_2026',15,'En un condicional `if ("0")`, ¿el bloque interno se ejecuta o se omite?','El bloque se ejecuta. En un condicional el valor se convierte a booleano, y **toda cadena no vacía es verdadera**, incluida `"0"`: lo que decide es que tenga caracteres, no lo que digan. La única cadena falsa es la vacía, `""`. Es una trampa clásica, porque el número `0` sí es falso y `"0"` se le parece a la vista.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(68,3,'json_2026',16,'¿Qué diferencia clave existe entre los operadores relacionales == y === en JavaScript?','`==` convierte tipos antes de comparar, así que `"5" == 5` es verdadero; `===` compara tipo y valor sin convertir nada, y por eso `"5" === 5` es falso. La (a) dice exactamente lo contrario y por eso es el distractor que separa al que sabe. La recomendación práctica es usar `===` siempre, salvo que se quiera la conversión a propósito y se sepa por qué.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(69,3,'json_2026',17,'Si intentas asignar un valor a un índice fuera del límite actual de un arreglo, ¿qué sucede?','El arreglo se estira hasta ese índice y su `length` crece para incluirlo. No hay error: los arreglos de JavaScript no tienen un tamaño reservado que pueda desbordarse. Las posiciones intermedias que quedaron sin valor se leen como `undefined`. Las otras tres suponen comportamientos que no existen: ni se lanza un `RangeError`, ni se ignora la asignación, ni se desplazan los índices ya ocupados.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(70,3,'json_2026',18,'¿Cómo afecta la modificación de un arreglo a sus referencias asignadas a otras variables?','Un arreglo es un objeto y las variables guardan una referencia a él, no una copia. Si dos variables apuntan al mismo arreglo, el cambio hecho a través de una se ve por la otra, porque hay un solo arreglo. Para obtener una copia hay que pedirla: `[...arr]` o `arr.slice()`, y aun así es una copia superficial. Es la causa de una parte grande de los errores con datos compartidos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(71,3,'json_2026',19,'¿Cuál es el propósito principal de la sentencia `continue` dentro de un ciclo `for`?','`continue` abandona la iteración en curso y salta a la siguiente, sin salir del ciclo. El que termina el bucle entero es `break`, que es la alternativa (a) y el par con el que siempre se confunde. `return` devuelve desde la función, no desde el ciclo, y no existe ninguna instrucción que reinicie el contador desde su valor inicial.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(72,3,'json_2026',20,'¿Qué diferencia conceptual rige entre un ciclo `while` y un bucle `do/while`?','`do/while` evalúa la condición **después** del bloque, así que el cuerpo corre al menos una vez aunque la condición sea falsa desde el principio; `while` la evalúa antes y puede no ejecutarse nunca. Esa es toda la diferencia, y es la que decide cuál usar: `do/while` sirve cuando hay que hacer algo primero y recién después preguntar si se repite.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(73,3,'json_2026',21,'En el contexto de arreglos asociativos simulados, ¿qué tipo subyacente de estructura son?','JavaScript no tiene arreglos asociativos de verdad: lo que se usa como tal son objetos, donde la clave de texto es el nombre de una propiedad. Por eso `obj["nombre"]` y `obj.nombre` son lo mismo. Los arreglos con índices numéricos son otra cosa y tienen `length` y métodos propios; matrices bidimensionales y tuplas inmutables no son estructuras nativas del lenguaje.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(74,3,'json_2026',22,'¿Por qué es una mala práctica declarar funciones internamente dentro de un bucle extenso?','Cada vuelta del ciclo crea una función nueva en memoria, aunque el código sea idéntico, y eso es trabajo y memoria sin motivo. La salida es declarar la función una vez fuera del bucle y llamarla dentro. No es un error de sintaxis ni rompe nada: el programa funciona, simplemente hace de más, y por eso es una mala práctica y no un fallo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(75,3,'json_2026',23,'¿Qué principio rige en las convenciones de "código limpio" (Clean Code) para nombrar variables?','El nombre tiene que decir qué guarda la variable o qué hace la función, de modo que el código se pueda leer sin ir a buscar la definición. `contadorDeIntentos` gana a `c` aunque sea más largo. Las otras tres proponen prácticas abandonadas o falsas: el largo de un nombre no consume memoria en tiempo de ejecución, la notación húngara cayó en desuso, y las mayúsculas se reservan por convención para constantes.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(76,3,'json_2026',24,'En un ciclo iterativo, ¿qué sucede si la condición de salida jamás se evalúa como falsa?','Si la condición nunca se vuelve falsa, el ciclo no termina: se queda girando y bloquea el hilo, que en el navegador significa una pestaña congelada. No hay ningún límite de iteraciones que lo detenga —la (a) inventa uno—, ni el compilador puede «optimizar» una condición que quizá sea correcta, ni el ciclo devuelve nada, porque nunca llega a salir.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(77,3,'json_2026',25,'¿Qué comportamiento describe la capacidad de alojar una función anónima dentro de una variable?','Que una función se pueda guardar en una variable, pasar como argumento y devolver desde otra función es lo que significa que las funciones sean ciudadanos de primera clase: valen lo mismo que cualquier otro dato. De ahí salen los callbacks y buena parte del estilo del lenguaje. Las otras tres nombran conceptos reales de JavaScript, pero ninguno describe lo que la pregunta plantea.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(78,3,'json_2026',26,'Si una función ejecuta un bloque de código pero omite la instrucción `return`, ¿qué devuelve?','Toda función devuelve algo, y si no se dice qué, devuelve `undefined`. No es un caso especial: es el valor por omisión del retorno. `null` habría que devolverlo a propósito, y `0` y `false` son valores concretos que nadie escribió. Conviene tenerlo claro porque `undefined` es lo que se recibe al usar el resultado de una función que en realidad no devolvía nada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(79,3,'json_2026',27,'¿Qué sucede si pasas menos argumentos a una función de los definidos en sus parámetros?','Los parámetros que no reciben argumento quedan en `undefined`, y la función corre igual. JavaScript no comprueba la cantidad de argumentos: pasar de menos —o de más— no es un error. De ahí vienen los valores por omisión, `function f(x = 10)`, que existen justamente para no tener que comprobar a mano si llegó `undefined`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(80,3,'json_2026',28,'¿Por qué el uso excesivo de variables globales está catalogado como un antipatrón riesgoso?','Cualquier parte del programa puede leer y escribir una variable global, así que dos trozos de código que no se conocen pueden pisarse el valor, y encontrar quién lo hizo es difícil porque el sospechoso es todo el archivo. Las otras tres dicen cosas falsas: las globales no ocupan menos, admiten cualquier tipo de dato, y son accesibles desde dentro de ciclos y condicionales.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(81,3,'json_2026',29,'¿Qué regla determina el acceso a variables dentro de funciones anidadas (lexical scoping)?','El alcance léxico se decide por dónde está escrita la función, no por dónde se la llama: una función interna ve sus propias variables, las de la función que la contiene, y las globales. Ese encadenamiento hacia afuera es lo que hace posibles los closures. Las otras tres niegan justamente esa cadena, que es lo que la pregunta evalúa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(82,3,'json_2026',30,'¿Qué efecto tiene declarar un parámetro con el mismo nombre que una variable global del scope?','Se llama shadowing: dentro de la función, el nombre se resuelve al parámetro y la variable global queda tapada mientras dure esa ejecución. No hay error ni conflicto —JavaScript permite repetir el nombre— y la global **no** se modifica: sigue intacta y vuelve a verse al salir de la función. Confundir «tapar» con «sobrescribir» es el error que la (c) recoge.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(83,3,'json_2026',31,'¿Qué palabra clave nativa y reservada da acceso dinámico a todos los parámetros en una función?','`arguments` es un objeto que existe dentro de toda función tradicional y contiene todos los argumentos recibidos, se hayan declarado como parámetros o no. `args`, `params` e `inputs` no son palabras del lenguaje. Conviene saber que `arguments` **no existe en las funciones flecha**, y que hoy se prefiere el parámetro rest —`function f(...args)`—, que sí da un arreglo de verdad.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(84,3,'json_2026',32,'¿Qué ocurre con la memoria de las variables locales al concluir la ejecución de su función?','Al terminar la función, sus variables locales dejan de ser alcanzables y el recolector de basura libera esa memoria cuando le toca; no hay que liberarla a mano. Hay una excepción que vale la pena tener presente desde ya, porque aparece poco después en el propio curso: si una función interna capturó esas variables —un closure—, siguen vivas después de que la función externa terminó, porque todavía queda quien las alcance. Las otras tres describen cosas que no pasan: no se quedan hasta reiniciar el navegador, no se exportan al ámbito global, y no se guardan en `localStorage`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(85,3,'json_2026',33,'Al acceder a una propiedad dinámica cuyo nombre está en una variable, ¿qué notación es obligatoria?','Cuando el nombre de la propiedad está guardado en una variable hay que usar corchetes, `objeto[variable]`, porque así se evalúa la variable y se usa su contenido como clave. Con punto, `objeto.variable`, se buscaría una propiedad llamada literalmente «variable». Las notaciones con flecha y con guion no existen en JavaScript; la de flecha es de PHP y C++.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(86,3,'json_2026',34,'¿Qué define estrictamente a un "método" en el paradigma orientado a objetos de JavaScript?','Un método no es una categoría aparte: es sencillamente una propiedad cuyo valor resulta ser una función. Por eso se puede agregar uno a un objeto ya creado con una asignación corriente, y por eso `typeof obj.metodo` responde `"function"`. Entender esto es lo que hace que después no sorprenda pasar métodos como argumentos o guardarlos en variables.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(87,3,'json_2026',35,'Si intentas consultar una propiedad que no existe dentro de un objeto literal, ¿qué evalúa JS?','Consultar una propiedad que no existe devuelve `undefined`, sin error. Eso es cómodo y a la vez peligroso: el programa sigue con un `undefined` que puede reventar más adelante, lejos de donde estuvo la causa. El `ReferenceError` de la (d) es para variables que no existen, que es otra cosa: acceder a una propiedad inexistente de un objeto que sí existe nunca lanza.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(88,3,'json_2026',36,'¿Qué función del objeto Math permite redondear un decimal hacia el entero superior más cercano?','`Math.ceil()` redondea siempre hacia arriba: `Math.ceil(4.1)` da 5. Las otras tres son reales y hacen otra cosa: `Math.floor()` redondea siempre hacia abajo, `Math.round()` al entero más cercano según el decimal, y `Math.trunc()` corta la parte decimal sin mirar. Con negativos se separan de verdad: `Math.ceil(-4.7)` da -4 y `Math.trunc(-4.7)` da -4, pero `Math.floor(-4.7)` da -5.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(89,3,'json_2026',37,'Para generar un número seudoaleatorio decimal entre 0 y casi 1, ¿qué invocación es la correcta?','`Math.random()` devuelve un decimal entre 0 incluido y 1 excluido. Nunca llega a 1, y por eso la fórmula habitual para un entero en un rango es `Math.floor(Math.random() * n)`. `Math.rand()`, `Math.rnd()` y `Math.getSeed()` no existen; la última además insinúa algo que JavaScript no ofrece: no hay forma de fijar la semilla del generador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(90,3,'json_2026',38,'¿Qué método de la instancia String extrae una porción de texto basada en índices de inicio y fin?','`slice(inicio, fin)` devuelve el trozo entre esos índices, sin incluir el final, y no modifica la cadena original —las cadenas son inmutables—. `split()` existe pero parte la cadena en un arreglo usando un separador; `splice()` es de arreglos y además muta; `extract()` no existe. Que `slice` funcione igual en cadenas y en arreglos ayuda a recordarlo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(91,3,'json_2026',39,'Al invocar el método `String.prototype.indexOf()`, ¿qué se retorna si la subcadena no existe?','`indexOf()` devuelve la posición de la primera coincidencia y `-1` si no encuentra nada. Se eligió `-1` porque cualquier posición válida es cero o mayor, así que no se confunde con un resultado real. Justamente por eso hay que compararlo con `-1` y no usarlo como booleano: la posición `0` es un hallazgo válido y es falsy, que es el error clásico. Cuando solo interesa saber si está, `includes()` es más claro.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(92,3,'json_2026',40,'¿Cuál es la diferencia estructural entre crear un string primitivo y usar `new String()`?','`new String("hola")` construye un objeto envoltorio, mientras que `"hola"` es un valor primitivo. Se nota al comparar: `typeof` responde `"object"` en el primero y `"string"` en el segundo, y `new String("a") === "a"` es falso. En la práctica no se usa `new String()`, porque el motor envuelve el primitivo solo cuando hace falta llamar a un método.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(93,3,'json_2026',41,'¿Qué recorre cada ciclo al aplicar `for...in` frente a `for...of` sobre un arreglo?','`for...in` recorre las **claves** —en un arreglo, los índices, y además como texto— y `for...of` recorre los **valores**. Por eso sobre arreglos casi siempre se quiere `for...of`. Y hay una razón más para no usar `for...in` con arreglos: también recorre propiedades heredadas o agregadas al objeto, así que puede devolver más de lo que uno espera.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(94,3,'json_2026',42,'Al invocar `sort()` sin argumentos sobre el arreglo [10, 9, 100], ¿en qué orden queda y por qué?','Queda `[10, 100, 9]`. Sin función comparadora, `sort()` convierte cada elemento a texto y ordena alfabéticamente, y como texto `"10"` va antes que `"100"` y este antes que `"9"`, porque compara carácter a carácter. Para ordenar números de verdad hay que dárselo escrito: `arr.sort((a, b) => a - b)`. Es uno de los comportamientos más sorprendentes del lenguaje y por eso se pregunta tanto.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(95,3,'json_2026',43,'En una estructura `switch`, ¿qué consecuencia acarrea omitir la sentencia `break` en un caso?','Sin `break`, la ejecución sigue cayendo hacia los casos siguientes y los ejecuta aunque no coincidan, hasta encontrar un `break` o terminar el `switch`. Se llama fall-through y a veces se usa a propósito, agrupando varios casos que comparten el mismo cuerpo. Lo que nunca hace es lanzar error, repetirse ni volver al principio.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(96,3,'json_2026',44,'¿Cuál es la sintaxis correcta del operador condicional ternario para asignar un valor?','La forma es `condición ? valorSiVerdadero : valorSiFalso`, y devuelve un valor, por eso se puede asignar directo. La (a) mezcla `if` con el ternario, que no se combinan; la (b) usa `|`, que es un operador de bits; y la (d) usa la flecha de las funciones. Es el único operador de JavaScript que toma tres operandos, de ahí el nombre.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(97,3,'json_2026',45,'¿Qué delimitador y qué marcador exige una plantilla literal para interpolar una expresión?','Las plantillas literales van entre comillas invertidas y la expresión se interpola con `${...}`. Dentro se puede poner cualquier expresión, no solo una variable, y además el texto puede ocupar varias líneas sin escapar nada, que es la otra ventaja frente a las comillas normales. Los marcadores `#{}`, `%%` y `@{}` son de otros lenguajes: el primero es de Ruby.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(98,3,'json_2026',46,'Si a un arreglo de diez elementos se le asigna `length = 4`, ¿qué le sucede a su contenido?','`length` es de lectura y escritura, y bajarlo trunca el arreglo: los elementos desde el índice 4 en adelante se descartan y no vuelven. Es la forma más corta de vaciar un arreglo, `arr.length = 0`. Las otras tres suponen protecciones que no existen: no es de solo lectura, no reordena nada y no hay capacidad reservada que pueda desbordarse.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(99,3,'json_2026',47,'Respecto al método `push()` sobre un arreglo, ¿dónde inserta y qué valor devuelve la llamada?','`push()` agrega al final y devuelve la nueva longitud, no el elemento. Confundirlo importa cuando se encadena o se guarda el resultado. El que agrega al principio es `unshift()`, y también devuelve la longitud. Ninguno de los dos devuelve una copia: los dos modifican el arreglo original.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(100,3,'json_2026',48,'¿Cuál es la distinción sustantiva entre invocar `slice()` y aplicar `splice()` sobre un arreglo?','`slice()` devuelve un trozo nuevo y deja el original intacto; `splice()` modifica el arreglo en su sitio, quitando o insertando elementos, y devuelve los que sacó. Los nombres se parecen tanto que la confusión es habitual, y la consecuencia no es menor: uno destruye datos y el otro no. La (d) es falsa: `slice` existe en cadenas **y** en arreglos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(101,3,'json_2026',49,'Al ejecutar `parseInt("08px")`, ¿qué valor entrega el analizador y bajo qué criterio se detiene?','Devuelve el número `8`. `parseInt` lee desde el principio mientras encuentre caracteres válidos y se detiene en el primero que no lo sea, aquí la `p`, devolviendo lo leído hasta ahí. El `0` inicial no lo vuelve octal: eso ocurría en motores antiguos y el estándar lo fijó en decimal salvo que se indique la base, `parseInt("08", 10)`. Devolvería `NaN` solo si no hubiera ningún dígito al principio, como en `parseInt("px8")`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(102,3,'json_2026',50,'Si un objeto se declara con `const`, ¿qué operaciones permanecen permitidas sobre él?','`const` protege la **asignación del identificador**, no el contenido del objeto. Se pueden modificar, agregar y borrar propiedades; lo que falla es `obj = otroObjeto`. Para impedir también los cambios internos existe `Object.freeze()`, que es otra cosa y hay que pedirla. Suponer que `const` congela el objeto es uno de los malentendidos más extendidos del lenguaje.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(103,3,'js_2026',1,'En condicionales, ¿qué sucede al evaluar una expresión con coerción de tipos estricta (===)?','`===` compara valor y tipo sin convertir nada: si los tipos difieren, el resultado es falso y ahí termina. Por eso `"5" === 5` da falso mientras `"5" == 5` da verdadero. La (a) describe a `==`, que es el operador contrario; la (c) inventa un error que no ocurre —comparar tipos distintos es legal—; y la (d) describe a `||`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(104,3,'js_2026',2,'¿Qué evalúa correctamente la expresión ''typeof null'' en JavaScript por un error histórico del lenguaje?','`typeof null` responde `"object"`, y es un error conocido que viene de la primera implementación de JavaScript en 1995: internamente los valores llevaban una etiqueta de tipo y la de `null` coincidía con la de los objetos. Nunca se arregló porque hacerlo rompería código existente. Para comprobar si algo es `null` hay que compararlo directo: `valor === null`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(105,3,'js_2026',3,'¿Cuál es la precedencia al evaluar una expresión matemática compleja en código JavaScript?','Multiplicación y división se evalúan antes que suma y resta, y los paréntesis mandan sobre todo. Los operadores lógicos tienen precedencia **menor** que los aritméticos, así que la (a) está al revés; la asignación es de las últimas en evaluarse, no de las primeras; y la (d) describe una evaluación sin precedencia, que no es la de JavaScript ni la de la aritmética.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(106,3,'js_2026',4,'¿Qué método de arreglos elimina el último elemento y retorna su valor simultáneamente?','`pop()` quita el último elemento y devuelve ese elemento, así que sirve para sacar y usar en un solo paso. `shift()` hace lo mismo pero con el primero; `unshift()` agrega al principio; y `push()` agrega al final. Los cuatro modifican el arreglo original, y conviene aprenderlos por pares: `push`/`pop` al final, `unshift`/`shift` al principio.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(107,3,'js_2026',5,'¿Qué problema crítico ocurre al declarar variables iteradoras globales en ciclos anidados (for)?','Si los dos ciclos comparten la misma variable global como contador, el ciclo interior la deja en su valor final y el exterior continúa desde ahí, así que el exterior no completa sus vueltas. La salida es declarar el contador con `let` dentro de cada `for`, que le da a cada ciclo el suyo. No hay error de sintaxis ni desbordamiento: el programa corre y da un resultado equivocado, que es peor.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(108,3,'js_2026',6,'¿Cuál es el riesgo de modificar un arreglo mientras se itera linealmente sobre él (ej: borrando)?','Al borrar un elemento, los que están detrás se corren una posición hacia atrás mientras el índice del ciclo sigue avanzando, así que el que ocupó el lugar del borrado se salta sin visitarse. Las salidas habituales son recorrer de atrás hacia adelante, o construir un arreglo nuevo con `filter()` en vez de modificar el que se está recorriendo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(109,3,'js_2026',7,'¿Qué ocurre con las variables declaradas dentro de una función regular utilizando ''var''?','`var` tiene alcance de **función**: la variable existe en toda la función donde se declaró, y no fuera. Ese es su contraste con `let` y `const`, que tienen alcance de bloque y por eso desaparecen al cerrar un `if` o un `for`, lo que describe la (d). Y no se vuelve global: eso pasa al asignar sin declarar, que es otra cosa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(110,3,'js_2026',8,'Si una función no tiene una sentencia return explícita, ¿qué valor retorna por defecto al invocarse?','Sin `return`, la función devuelve `undefined`. Es el valor por omisión y no un caso especial. Los otros tres son valores concretos que alguien tendría que haber escrito: `null` significa vacío a propósito, `false` es un booleano y `0` un número. Reconocer un `undefined` inesperado suele ser la pista de que una función no devolvía lo que se creía.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(111,3,'js_2026',9,'¿Cuál es el problema estructural causado por abusar de las variables globales en funciones?','Cualquier función puede escribir una variable global, así que dos funciones que no se conocen pueden pisarse el valor; y como todas dependen del mismo estado compartido, quedan acopladas y no se pueden mover ni probar por separado. Las otras tres describen problemas inventados: las globales no tocan la memoria de video, no bloquean el DOM y no impiden anidar funciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(112,3,'js_2026',10,'¿Cuál es la sintaxis correcta para acceder a un método interno de objeto mediante la notación de punto?','La notación de punto es `objeto.metodo()`: el nombre del objeto, un punto, el nombre del método y los paréntesis que lo invocan. `->` es de PHP y C++, `::` es de C++ y de la sintaxis de clases de otros lenguajes, y `objeto[metodo()]` usa corchetes, que sí existen en JavaScript pero con otro sentido: ahí se evaluaría `metodo()` y su resultado se usaría como nombre de propiedad.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(113,3,'js_2026',11,'Al llamar String.prototype.slice(1, -1) en la cadena "Prueba", ¿qué porción de texto se retorna?','Devuelve `"rueb"`. `slice(1, -1)` empieza en el índice 1, que es la `r`, y el `-1` cuenta desde el final, así que corta antes del último carácter y deja fuera la `a` final. La `P` inicial se pierde por empezar en 1 y la `a` final por el índice negativo. Poder usar índices negativos para contar desde atrás es lo que la pregunta evalúa, y es propio de `slice`: `substring` no lo admite.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(114,4,'json_2026',1,'¿Qué pilar de POO oculta el estado interno de un objeto y exige métodos para alterarlo?','El encapsulamiento es el pilar que esconde el estado interno y obliga a pasar por métodos para tocarlo, de modo que el objeto controla cómo se lo modifica. Los otros tres existen y hacen otra cosa: el polimorfismo permite que objetos distintos respondan al mismo método, la abstracción expone qué hace algo y esconde cómo, y la herencia múltiple ni siquiera es de JavaScript — un objeto hereda de un solo prototipo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(115,4,'json_2026',2,'En JS pre-ES6, ¿qué mecanismo emula la herencia de clases tradicional?','Antes de ES6 no había clases, y la herencia se armaba con la cadena de prototipos: cada objeto guarda un enlace a otro, y al pedir una propiedad que no tiene, el motor sube por esa cadena hasta encontrarla o llegar a `null`. Las clases de ES6 no cambiaron eso: son azúcar sintáctico sobre el mismo mecanismo. Las otras tres nombran cosas que JavaScript no tiene: clases abstractas puras, mixins estáticos globales, y desde luego no se manipula la memoria a mano.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(116,4,'json_2026',3,'¿Qué método convierte un objeto literal de JavaScript a una cadena de texto en formato JSON?','`JSON.stringify()` convierte un valor de JavaScript a texto en formato JSON. El que va en la dirección contraria es `JSON.parse()`, que es la (a) y el par con el que siempre se confunde: uno serializa y el otro interpreta. `Object.toJSON()` y `String.fromJSON()` no existen. Conviene recordar que `stringify` **descarta** las funciones y las propiedades `undefined`, lo que enlaza con la pregunta sobre qué tipos admite JSON.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(117,4,'json_2026',4,'¿Qué restricción estricta de sintaxis aplica al estándar JSON que difiere de objetos JS?','En JSON las claves van **siempre** entre comillas dobles: `{"nombre": "Ana"}`. Los objetos de JavaScript son más laxos —admiten claves sin comillas y con comillas simples—, y esa diferencia es la fuente del error más común al escribir JSON a mano. Las otras tres describen permisos que JSON no da: no admite comentarios, no admite funciones como valores, y no perdona las claves sin comillas aunque sean alfanuméricas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(118,4,'json_2026',5,'En POO, ¿qué término define a una entidad concreta creada a partir de una clase plantilla?','Una instancia es el objeto concreto que se crea a partir de una clase: la clase es el plano y la instancia es la casa construida. Un prototipo es el objeto del que se hereda, no lo que se construye; una interfaz describe un contrato y JavaScript no las tiene como constructo del lenguaje; y un método estático pertenece a la clase y no a los objetos que salen de ella.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(119,4,'json_2026',7,'Al instanciar un objeto con `new`, ¿qué función especial de la clase se ejecuta primero?','El `constructor()` es lo primero que corre al usar `new`: recibe los argumentos y prepara el objeto. `super()` también corre pronto, pero **dentro** del constructor y solo cuando hay herencia — y ahí hay una regla que conviene saber: si la clase extiende a otra, hay que llamar a `super()` antes de usar `this`. `render()` e `init()` no son nada del lenguaje; son convenciones de bibliotecas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(120,4,'json_2026',8,'En notación literal de objetos JS, ¿cómo defines un método interno correctamente?','En notación literal, un método es una propiedad cuyo valor es una función: `metodo: function() {}`. La (b) es la sintaxis de una función suelta y no cabe dentro de un objeto literal; la (c) confunde la flecha con la asignación, y la (d) es de Python. Desde ES6 existe además la forma abreviada `metodo() {}`, que significa exactamente lo mismo y es la que se ve hoy en el código nuevo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(121,4,'json_2026',9,'¿Qué tipo de dato nativo JS no es válido para ser almacenado en una estructura JSON?','JSON no tiene tipo función, así que una función no se puede guardar en él. `JSON.stringify()` no falla al encontrarse una: **la omite en silencio**, que es peor que fallar, porque el objeto viaja incompleto sin que nadie avise. Los otros tres —booleanos, números y arreglos— son tipos que JSON admite sin problema, junto con cadenas, objetos y `null`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(122,4,'json_2026',10,'En el prototipo de JS, ¿qué propiedad apunta al objeto del cual hereda sus métodos base?','`__proto__` es la propiedad que apunta al objeto del que se hereda, y recorrerla es recorrer la cadena de prototipos. Las otras tres no existen. Conviene saber que hoy `__proto__` está desaconsejada aunque siga funcionando: lo recomendado es `Object.getPrototypeOf(obj)` para leerla y `Object.setPrototypeOf()` para cambiarla, y que no se confunde con `prototype`, que es otra cosa y vive en las funciones constructoras.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(123,4,'json_2026',11,'¿Qué característica fundamental diferencia a `let` frente a `var` en su ámbito de alcance?','`let` tiene alcance de **bloque**: existe dentro de las llaves donde se declaró y desaparece al salir, así que un `let` dentro de un `if` o un `for` no se ve fuera. `var` tiene alcance de función, que es más ancho y la causa de muchos errores con contadores de ciclos. Las otras tres son falsas: `let` no es global, sí permite cambiar el tipo del valor, y `var` no desaparece al salir de un bloque.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(124,4,'json_2026',12,'¿Qué ocurre si intentas reasignar un nuevo valor escalar a una variable definida con `const`?','Reasignar una variable declarada con `const` lanza un `TypeError`. Es un error de verdad, no un aviso: la asignación no ocurre y, si nadie lo atrapa, corta la ejecución de ese script. Ojo con el alcance de la protección, que es lo que más se confunde: `const` protege **el identificador**, no el contenido. Sobre un objeto declarado con `const` se pueden agregar, cambiar y borrar propiedades; lo que falla es apuntarlo a otro objeto.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(125,4,'json_2026',13,'¿Qué comportamiento léxico particular tienen las Arrow Functions (`=>`) respecto a `this`?','Las funciones flecha no tienen `this` propio: usan el del contexto donde fueron escritas. Por eso resuelven el problema clásico de perder `this` dentro de un callback, y por eso **no sirven como métodos de un objeto** cuando se espera que `this` apunte a ese objeto. Es un comportamiento léxico —lo decide dónde está escrita la función, no cómo se la llama— y es la diferencia práctica más importante frente a `function`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(126,4,'json_2026',14,'¿Qué operador ES6 permite desestructurar un arreglo y agrupar el resto de sus elementos?','El operador rest agrupa lo que sobra en un arreglo nuevo: `const [primero, ...resto] = lista`. Comparte los tres puntos con el spread y por eso se confunden, pero hacen lo contrario: **rest recoge y spread reparte**. Lo que decide cuál es cuál es la posición — a la izquierda de una asignación o en los parámetros de una función, recoge; dentro de un arreglo, un objeto o una llamada, reparte.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(127,4,'json_2026',15,'En clases ES6, ¿qué palabra clave invoca al constructor de la clase padre al usar herencia?','`super()` llama al constructor de la clase padre, y hay que invocarlo antes de usar `this` en una clase que extiende a otra. `extends` existe pero es la palabra que declara la herencia en la cabecera de la clase, no una función que se invoque; `parent()` y `base()` no son nada de JavaScript. `super` también sirve para llamar métodos del padre desde un método propio: `super.metodo()`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(128,4,'json_2026',16,'¿Qué mecanismo en ES6 permite expandir elementos de un arreglo dentro de otro arreglo nuevo?','El operador spread expande los elementos de un arreglo dentro de otro: `[...a, ...b]`. `Array.concat()` consigue un resultado parecido y por eso es un buen distractor, pero la pregunta es por el mecanismo de ES6. Ojo con un límite que importa: el spread hace una copia **superficial**, así que los objetos de dentro se siguen compartiendo entre el arreglo viejo y el nuevo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(129,4,'json_2026',17,'¿Cómo se define correctamente un método estático dentro de una clase en ES6?','Un método estático se declara anteponiendo `static` al nombre, y pertenece a la clase y no a sus instancias: se invoca como `Clase.metodo()` y no desde un objeto creado con `new`. La (b) define una propiedad con una función flecha, que no es lo mismo; la (c) mezcla dos sintaxis que no se combinan; y la (d) usa un decorador, que no es JavaScript estándar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(130,4,'json_2026',18,'¿Qué palabra clave se usa en un módulo ES6 para exponer una función y usarla en otro archivo?','`export` es la palabra de los módulos ES6 para exponer algo a otro archivo. `module.exports` es la forma de CommonJS, la de Node antes de los módulos ES, y por eso es el distractor que separa los dos sistemas — que no se mezclan en el mismo archivo. `expose` e `include` no existen. En este proyecto se usa `export`, porque las páginas cargan sus scripts con `type="module"`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(131,4,'json_2026',19,'¿Cuál es la sintaxis correcta para importar un módulo exportado por defecto en ES6?','Lo exportado por defecto se importa sin llaves y con el nombre que uno quiera: `import Modulo from ''./archivo.js''`. Con llaves, la (a), se importan las exportaciones **nombradas**, y ahí el nombre sí tiene que coincidir. `require()` es de CommonJS. Un archivo puede tener una sola exportación por defecto y todas las nombradas que quiera.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(132,4,'json_2026',20,'¿Qué ventaja principal ofrece la interpolación de strings mediante template literals (` `)?','Dentro de una plantilla literal, `${...}` evalúa cualquier expresión de JavaScript y pega su resultado en el texto: no solo variables, también llamadas a funciones y operaciones. La segunda ventaja, que la pregunta no menciona, es que el texto puede ocupar varias líneas sin escapar nada. Las otras tres prometen cosas que no ocurren: no cifra, no convierte a número y no compila a binario.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(133,4,'json_2026',21,'¿Qué representa la estructura subyacente jerárquica del DOM (Document Object Model)?','El DOM es un árbol de nodos: el documento es la raíz y cada etiqueta, atributo y trozo de texto es un nodo con sus hijos. Esa forma es lo que permite recorrerlo, buscar dentro y modificarlo desde JavaScript. No es una lista plana de cadenas de HTML —esa es la vista del código fuente, no la del documento cargado— ni es estático ni es una base de datos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(134,4,'json_2026',22,'¿Qué método estándar de JS añade un nuevo nodo hijo al final de un elemento padre en el DOM?','`appendChild()` agrega un nodo como último hijo del elemento sobre el que se lo llama. Las otras tres no existen con esos nombres. Vale la pena conocer a sus vecinos reales: `insertBefore()` coloca antes de un nodo concreto, y los modernos `append()`, `prepend()`, `before()` y `after()` admiten además texto suelto y varios nodos a la vez.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(135,4,'json_2026',23,'En la fase de captura de eventos del DOM, ¿en qué dirección se propaga el evento?','La captura va **desde la raíz hacia el elemento objetivo**: el evento baja por el árbol antes de llegar a su destino. Es la primera de las tres fases —captura, destino y burbujeo— y es la menos usada, porque `addEventListener` escucha en burbujeo salvo que se le pase `true` o `{ capture: true }`. La (a) describe el burbujeo, que es el camino de vuelta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(136,4,'json_2026',25,'Si se asignan varios manejadores al mismo evento en un nodo con `addEventListener`, ¿qué pasa?','Se ejecutan todos, en el orden en que se registraron. Ésa es una de las razones de ser de `addEventListener` frente a asignar `onclick`, que sí se sobrescribe: con `onclick` solo sobrevive el último manejador. No hay error de duplicidad, y ninguno bloquea a los siguientes — salvo que uno llame a `stopImmediatePropagation()`, que es lo único que corta la lista.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(137,4,'json_2026',26,'¿Qué propiedad del objeto evento (Event) identifica el nodo exacto que originó dicho evento?','`event.target` es el nodo donde el evento se originó de verdad. Se distingue de `event.currentTarget`, que es el elemento en el que está puesto el manejador y que es la (a): en un manejador delegado sobre un contenedor, `currentTarget` es el contenedor y `target` es el hijo que recibió el clic. Esa diferencia es exactamente lo que hace posible la delegación de eventos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(138,4,'json_2026',27,'¿Qué método detiene la propagación (burbujeo) de un evento hacia sus nodos padres en el DOM?','`stopPropagation()` corta el viaje del evento hacia los nodos padres. No se confunde con `preventDefault()`, que es la (a) y cancela la acción por omisión del navegador —enviar el formulario, seguir el enlace— sin detener la propagación: son dos cosas independientes y a veces se usan juntas. `cancelBubble` existe como propiedad heredada de Internet Explorer, pero no como método, y `stopBouncing()` no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(139,4,'json_2026',28,'Para modificar las clases CSS de un nodo de forma segura y dinámica, ¿qué propiedad usarías?','`classList` da una interfaz pensada para esto —`add()`, `remove()`, `toggle()`, `contains()`— y toca una sola clase sin pisar las demás. `className` es la (a) y es la forma antigua: guarda todas las clases en una cadena, así que asignarle un valor **borra las que ya estaban**, y ése es el «de forma segura» que la pregunta pide. `style` cambia estilos en línea, no clases.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(140,4,'json_2026',29,'¿Qué evento ocurre cuando el DOM inicial HTML es cargado y parseado completamente?','`DOMContentLoaded` se dispara cuando el HTML terminó de parsearse y el árbol está armado, sin esperar imágenes ni hojas de estilo. `window.onload`, la (a), espera además a que todos esos recursos carguen, así que llega bastante después: es el par que hay que saber distinguir. `document.onready` no existe en JavaScript nativo — es de jQuery, `$(document).ready()` —, y `HTMLParsedEvent` no existe en ninguna parte.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(141,4,'json_2026',30,'¿Qué método altera dinámicamente el contenido de texto de un nodo omitiendo etiquetas HTML?','`textContent` trata lo que se le da como texto plano, así que las etiquetas se ven tal cual en vez de interpretarse. `innerHTML` sí las interpreta, y por eso es la (a) y es la puerta de entrada de los ataques XSS cuando el texto viene de fuera. En este proyecto esa distinción no es teórica: el banco de preguntas es contenido de origen externo y todo lo que se pinta con `innerHTML` pasa antes por una función de escapado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(142,4,'json_2026',31,'¿Por qué JavaScript es considerado un lenguaje de un único hilo (single-threaded) por diseño?','JavaScript tiene un solo call stack, así que ejecuta una instrucción a la vez y nada corre en paralelo dentro de él. Lo que da la impresión de simultaneidad es que las operaciones lentas —red, temporizadores— las atiende el entorno por fuera y devuelve sus callbacks a una cola, que es de lo que se ocupa el bucle de eventos. Las otras tres describen limitaciones inventadas: sí hay ciclos, sí hay varios archivos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(143,4,'json_2026',32,'En el contexto del Event Loop, ¿qué componente encola los callbacks de operaciones asíncronas?','La cola de callbacks es donde esperan los callbacks de las operaciones asíncronas ya terminadas, hasta que el call stack se vacía y el bucle de eventos los pasa a ejecutar. Las otras dos piezas de la lista son reales y tienen otro oficio: el call stack ejecuta, y el montículo guarda los objetos. Conviene saber que las promesas usan una cola aparte y con prioridad, la de microtareas, que se vacía antes que ésta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(144,4,'json_2026',34,'¿Qué estados fundamentales posee una Promesa en JavaScript durante su ciclo de vida lógico?','Una promesa está `pending` mientras la operación no termina, y de ahí pasa a `fulfilled` si salió bien o a `rejected` si falló. Ese paso ocurre **una sola vez** y es definitivo: una promesa resuelta no vuelve atrás ni cambia de valor. Se oye además la palabra `settled`, que no es un cuarto estado sino el nombre de «ya no está pendiente», o sea cumplida o rechazada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(145,4,'json_2026',35,'¿Qué método de una Promesa se ejecuta siempre, sin importar si fue resuelta o rechazada?','`.finally()` corre pase lo que pase, y sirve para lo que hay que hacer en los dos casos: cerrar una conexión, quitar un indicador de carga. No recibe el valor ni el error, justamente porque no sabe cuál de los dos ocurrió. `.then()` atiende el éxito, `.catch()` el fallo, y `.all()` ni siquiera es un método de la instancia sino de `Promise`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(146,4,'json_2026',36,'Al encadenar bloques `.then()`, ¿qué debe retornar el bloque actual para pasarlo al siguiente?','Lo que devuelve un `.then()` se convierte en el valor que recibe el siguiente. Si devuelve un valor corriente, se pasa tal cual; si devuelve una promesa, la cadena **espera** a que se resuelva y pasa su resultado. Esa segunda regla es la que permite encadenar operaciones asíncronas en vertical en vez de anidarlas. Y hay una trampa muy común: si el bloque no devuelve nada, el siguiente recibe `undefined`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(147,4,'json_2026',37,'Si usas la palabra clave `await` dentro de una función, ¿qué requisito debe tener esa función?','`await` solo se puede usar dentro de una función declarada `async`; fuera de ella es un error de sintaxis. La (c) suena razonable y es falsa: el `try/catch` es recomendable para atrapar el fallo, pero no es requisito para que `await` funcione. Conviene saber que desde ES2022 los módulos admiten `await` en el nivel superior, sin función que lo envuelva — pero solo en módulos, y la pregunta habla de una función.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(148,4,'json_2026',38,'¿Qué bloque atrapa correctamente una Promesa rechazada dentro de una función `async`?','Dentro de una función `async`, un `await` sobre una promesa rechazada lanza como si fuera una excepción corriente, así que se atrapa con `try/catch`. Ésa es la forma idiomática y la razón de ser de la sintaxis: el manejo de errores del código asíncrono vuelve a ser el de siempre. Conviene saber que el `.catch()` encadenado tampoco es un error —`await promesa.catch(...)` recoge el rechazo igual—, pero mezcla los dos estilos en la misma línea y se lee peor. Las otras dos alternativas sí son falsas: un `if(error) throw` no atrapa nada, y `window.onerror` no ve los rechazos de promesas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(149,4,'json_2026',39,'¿Qué método procesa un array de Promesas y falla si al menos una de las Promesas es rechazada?','`Promise.all()` espera a que todas se cumplan y falla en cuanto una se rechaza, descartando el resto de los resultados. Es lo que se quiere cuando todas las piezas son necesarias. Las otras tres existen y tienen otra política: `race()` devuelve la primera que se resuelva o rechace, `any()` la primera que se **cumpla** ignorando los rechazos, y `allSettled()` espera a todas y no falla nunca — informa qué pasó con cada una.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(150,4,'json_2026',40,'¿Qué retorna intrínsecamente cualquier función que ha sido declarada con el prefijo `async`?','Una función `async` devuelve siempre una promesa, aunque su `return` sea un número. Si devuelve un valor corriente, la promesa se cumple con ese valor; si lanza, se rechaza con el error. De ahí se sigue algo que conviene tener claro: llamarla sin `await` no da el valor, da la promesa. Y no bloquea el hilo principal — eso es justo lo que `async/await` viene a evitar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(151,4,'json_2026',41,'En la API XHR (XMLHttpRequest), ¿qué estado numérico del `readyState` indica éxito completo?','`readyState` recorre los valores 0 a 4, y el 4 —`DONE`— es el único que indica que el intercambio terminó. Ahora bien, **terminar no es lo mismo que salir bien**, y ésa es la distinción que hay que llevarse: una respuesta 404 o 500 llega igual con `readyState` 4. Para saber si hubo éxito se mira aparte `xhr.status`, comprobando que esté entre 200 y 299. El patrón completo es comprobar las dos cosas: primero que `readyState` sea 4, y recién entonces qué dice `status`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(152,4,'json_2026',42,'Al realizar una petición con XHR, ¿qué evento detecta cambios en el estado de la comunicación?','`onreadystatechange` es el manejador que XHR llama cada vez que cambia su `readyState`, y dentro de él se comprueba si ya llegó al 4. `onstatechange` no existe. `onloadend` y `onprogress` sí existen en la API moderna de XHR y por eso son buenos distractores, pero la pregunta apunta al mecanismo clásico, que es el que se ve en el material del examen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(153,4,'json_2026',43,'¿Qué código de estado HTTP 2xx devuelve habitualmente una API REST al responder con éxito?','Los tres son códigos 2xx y una API REST usa cada uno según lo que hizo: `200 OK` para una lectura o una operación con cuerpo de respuesta, `201 Created` cuando se creó un recurso, y `204 No Content` cuando la operación salió bien y no hay nada que devolver — típico de un borrado. La respuesta es «todos», y lo que la pregunta evalúa es saber que el éxito no es un solo código.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(154,4,'json_2026',44,'En contraposición a XHR, ¿qué estructura retorna por defecto el método `fetch()` en JavaScript?','`fetch()` devuelve una promesa, y ésa es su diferencia de fondo con XHR: se encadena con `.then()` o se espera con `await` en vez de registrar manejadores. Conviene recordar que hacen falta **dos** pasos asíncronos para llegar al dato: uno para la respuesta y otro para leer su cuerpo con `.json()`, que también devuelve una promesa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(155,4,'json_2026',45,'Al usar `fetch()`, ¿qué método extrae el cuerpo de la respuesta asíncrona a un objeto JS?','`response.json()` lee el cuerpo de la respuesta y lo convierte en un objeto de JavaScript. Devuelve una promesa, así que hay que esperarla: es el segundo `await` del patrón. Sus hermanos son `text()`, `blob()` y `formData()`, según lo que venga. Y el cuerpo se puede leer **una sola vez**: intentarlo dos veces sobre la misma respuesta falla.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(156,4,'json_2026',47,'¿Qué propiedad del objeto `Response` en `fetch()` indica si la solicitud HTTP fue un éxito (2xx)?','`response.ok` es `true` cuando el código está entre 200 y 299. Es la comprobación que hay que hacer siempre, porque `fetch` **no rechaza la promesa ante un error HTTP**: un 404 llega como respuesta cumplida con `ok` en falso. Las otras tres no existen, salvo `statusText`, que es un texto descriptivo y no un booleano.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(157,4,'json_2026',48,'Para enviar datos POST mediante `fetch()`, ¿en qué parámetro incluyes el payload JSON?','El cuerpo de la petición va en `body`, y si son datos JSON hay que serializarlos antes con `JSON.stringify()`: `body` recibe texto, no un objeto. Junto a él van `method: ''POST''` y la cabecera `Content-Type`. `headers` lleva las cabeceras, `mode` controla el comportamiento respecto de CORS, y `params` no es una opción de `fetch`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(158,4,'json_2026',49,'¿Qué cabecera HTTP (header) debes enviar para avisarle a la API que envías formato JSON?','`Content-Type: application/json` describe **lo que se está enviando**, y es lo que permite al servidor interpretar el cuerpo. Se confunde con `Accept`, la (a), que dice lo que se espera **recibir**: son direcciones opuestas y a veces se mandan las dos. Enviar JSON sin esa cabecera es una de las causas más frecuentes de que una API responda con un error de formato.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(159,4,'json_2026',50,'¿Qué riesgo de seguridad ocurre al consumir APIs ajenas sin validación de origen permitida?','Lo que ocurre es que el navegador **bloquea la respuesta** si el servidor ajeno no autoriza tu origen con sus cabeceras CORS. Conviene entender bien de qué lado está esto: CORS no es un ataque ni un agujero, es el navegador protegiendo al usuario, y por eso no se «desactiva» desde el código del cliente — se resuelve en el servidor que responde. Las otras tres nombran riesgos reales que no son éste.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(160,4,'js_2026',1,'¿Cómo implementa internamente JavaScript la herencia entre objetos sin usar la sintaxis de clases de ES6?','JavaScript hereda por prototipos: cada objeto guarda un enlace a otro, y las propiedades que no encuentra en sí mismo las busca subiendo por esa cadena. Las clases de ES6 no cambiaron el mecanismo, solo le dieron una sintaxis familiar. Las otras tres describen técnicas que no son la herencia del lenguaje: copiar propiedades es composición, clonar con JSON produce objetos sueltos sin cadena, y no hay clases abstractas nativas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(161,4,'js_2026',2,'En formato JSON válido, ¿cuál es la regla estricta para escribir los nombres de las claves (keys)?','Las claves de JSON van siempre entre comillas **dobles**. Las simples no valen —son legales en JavaScript pero no en JSON— y omitirlas tampoco, aunque la clave no tenga espacios. Es la regla que más se rompe al escribir JSON a mano, y el error que devuelve `JSON.parse()` suele señalar una posición y no la causa, así que conviene reconocerla de memoria.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(162,4,'js_2026',3,'¿Qué pilar de la POO permite que objetos de distintas clases respondan a una misma invocación de método?','El polimorfismo es que objetos de clases distintas respondan al mismo mensaje, cada uno a su manera: llamar a `area()` sobre un círculo y sobre un cuadrado y que cada uno haga su cálculo. El encapsulamiento esconde el estado, la abstracción esconde el cómo, y la herencia múltiple no existe en JavaScript. En un lenguaje dinámico como éste el polimorfismo sale casi solo: basta con que el método exista.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(163,4,'js_2026',4,'¿Qué ocurre si declaramos una variable con let e intentamos acceder a ella antes de su inicialización?','Lanza un `ReferenceError`. La variable **sí** se eleva, pero queda en la zona muerta temporal —la Temporal Dead Zone— desde el inicio del bloque hasta su declaración, y tocarla ahí es un error. Es la diferencia práctica con `var`, que en esa situación devuelve `undefined` y deja pasar el problema. La (d) describe justamente el comportamiento de `var`, y por eso es el distractor que separa al que entiende el hoisting del que lo recita.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(164,4,'js_2026',5,'¿Qué diferencia principal tiene una función flecha (arrow function) frente a una función tradicional?','Una función flecha no tiene `this` propio: toma el del lugar donde está escrita. De ahí sale su uso más común —callbacks que necesitan el `this` de fuera— y también su límite: no sirven como métodos cuando se espera que `this` sea el objeto. Tampoco tienen `arguments` propio ni se pueden usar con `new`. Las otras tres son inventadas: no devuelven JSON, no obligan a `function` y no limitan los parámetros.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(165,4,'js_2026',6,'En módulos ES6, ¿qué sintaxis permite exportar múltiples funciones nombradas desde un mismo archivo?','`export { func1, func2 };` exporta varias funciones nombradas, y quien las importe tiene que usar llaves y los mismos nombres. La (a) exporta un objeto por defecto, que es otra cosa y se importa distinto; la (b) es CommonJS; y la (d) confunde exportar con importar. También se puede poner `export` delante de cada declaración, que produce el mismo resultado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(166,4,'js_2026',7,'¿Qué fase del flujo de eventos del DOM ocurre propagándose desde el elemento objetivo hacia la raíz?','El burbujeo es la vuelta: el evento sube desde el elemento objetivo hacia la raíz, y por eso un manejador puesto en un contenedor se entera de los clics de sus hijos. Es lo contrario de la captura, que baja, y es la fase en la que `addEventListener` escucha por omisión. La fase de destino es el instante en el elemento mismo, y «delegación» no es una fase sino una técnica que se apoya en el burbujeo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(167,4,'js_2026',8,'¿Qué método detiene el comportamiento por defecto de un evento, como el refresco al enviar un formulario?','`preventDefault()` cancela lo que el navegador haría por su cuenta: enviar el formulario, seguir el enlace, marcar la casilla. No detiene la propagación — para eso está `stopPropagation()`, que es la (a) y el par con el que se confunde. `stopImmediatePropagation()` es más fuerte todavía: además de cortar la propagación, impide que corran los otros manejadores del mismo elemento.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(168,4,'js_2026',9,'¿Cuál es la estrategia más óptima para añadir eventos a múltiples elementos hijos generados dinámicamente?','La delegación de eventos: un solo manejador en el contenedor padre, que se entera de los clics de sus hijos gracias al burbujeo y decide con `event.target` cuál fue. Funciona con elementos creados **después** de registrar el manejador, que es justo lo que la pregunta plantea y lo que la (a) no resuelve — habría que registrar uno por cada elemento nuevo, y nadie se acuerda siempre.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(169,4,'js_2026',10,'¿Qué problema estructural del código resuelve principalmente el uso de Promesas frente a Callbacks clásicos?','Las promesas aplanan lo que los callbacks anidaban. Con callbacks, cada operación que depende de la anterior agrega un nivel de indentación hasta volver el código ilegible; con promesas, la cadena de `.then()` se lee en vertical, y con `async/await` se lee casi como código síncrono. No resuelven el consumo de memoria ni el bloqueo del hilo: el hilo no se bloqueaba tampoco con callbacks.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(170,4,'js_2026',11,'¿En qué estado interno queda una Promesa que ha completado su operación asíncrona con éxito?','`Fulfilled` es el estado de una promesa que terminó bien. `Pending` es mientras espera y `Rejected` es cuando falló. `Settled` es el mejor distractor de los cuatro porque **sí es un término real**, pero no es un estado: es el nombre que agrupa a las dos formas de terminar, cumplida o rechazada. Saber que existe y que no es un estado es exactamente lo que la pregunta separa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(171,4,'js_2026',12,'¿Qué estructura de control es necesaria para capturar errores de ejecución utilizando async/await?','Con `async/await` los errores se atrapan con `try/catch`, igual que en código síncrono: un `await` sobre una promesa rechazada lanza, y el `catch` lo recoge. Ésa es la ventaja de la sintaxis — que el manejo de errores vuelve a ser el de siempre, sin encadenar nada. El `.catch()` encadenado también funcionaría, pero pertenece al estilo de las cadenas de promesas y mezclarlo con `await` en la misma línea hace el código más difícil de leer. Las otras dos no sirven: ni un `if/else` ni un `switch` ven una excepción que se está lanzando.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(172,4,'js_2026',13,'A diferencia de XHR, ¿qué tipo de objeto nativo retorna por defecto la API Fetch al ser ejecutada?','`fetch()` devuelve una promesa, mientras que XHR devuelve un objeto sobre el que se registran manejadores. Ésa es la diferencia de forma que la pregunta busca. Ojo con la (b), que es el error más común de todos: `fetch` **no** devuelve el JSON ya interpretado — devuelve una respuesta, y sacar el objeto de dentro es un segundo paso asíncrono con `.json()`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(173,4,'js_2026',14,'Usando Fetch, ¿qué estado asume la promesa si el servidor responde con un error HTTP 404 (Not Found)?','La promesa **se cumple**. `fetch` solo se rechaza si la petición no se pudo hacer —sin red, DNS caído, CORS—; un 404 o un 500 son respuestas válidas del servidor y llegan como promesa cumplida con `response.ok` en falso. Es la trampa más importante de la API, porque un `try/catch` alrededor de un `fetch` **no** atrapa un 404: hay que comprobar `ok` a mano y lanzar si hace falta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(174,4,'js_2026',15,'¿Qué objeto nativo del navegador permite cancelar explícitamente una petición Fetch que está en progreso?','`AbortController` permite cancelar una petición en curso: se crea uno, se le pasa su `signal` a `fetch`, y al llamar a `abort()` la promesa se rechaza. Sirve para descartar una búsqueda que el usuario ya cambió, o para poner un tiempo límite. La (b) es el método equivalente de XHR y por eso es buen distractor, pero no funciona con `fetch`; `EventTarget` y `Promise.reject()` no cancelan nada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(175,5,'json_2026',1,'¿Qué característica fundamental distingue a un RDBMS de un sistema NoSQL documental?','Un motor relacional garantiza ACID —atomicidad, consistencia, aislamiento y durabilidad— como parte de su contrato, y eso es lo que lo distingue del enfoque documental clásico, que nació sacrificando esas garantías a cambio de flexibilidad y escala. Las otras tres describen rasgos del lado NoSQL: el esquema flexible, el almacenamiento en grafos y la ausencia de SQL. Conviene saber que la frontera se ha ido borrando —varios motores documentales ofrecen hoy transacciones ACID—, pero la distinción sigue siendo la que el examen evalúa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(176,5,'json_2026',2,'¿Cuál es el rol principal del motor relacional en la arquitectura de un RDBMS?','El motor relacional recibe una consulta declarativa —qué se quiere, no cómo obtenerlo—, decide el plan de ejecución y lo ejecuta: qué índice usar, en qué orden cruzar las tablas, cuándo filtrar. Ahí es donde se gana o se pierde el rendimiento. Las otras tres describen oficios de otras piezas: no compila a binarios, no dibuja interfaces, y los respaldos son una tarea aparte.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(177,5,'json_2026',3,'¿Qué protocolo se utiliza comúnmente para establecer la conexión a un motor RDBMS?','La conexión a un motor relacional viaja por TCP/IP cuando el cliente está en otra máquina, o por un socket local cuando está en la misma. Encima de ese transporte va el protocolo propio del motor, que no es HTTP. Las otras tres son protocolos reales de otros oficios: SMTP y POP3 mueven correo, FTP y SFTP mueven archivos, y REST es un estilo para APIs web, no para hablar con una base.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(178,5,'json_2026',4,'En el contexto de un RDBMS, ¿qué es un "catálogo de sistema"?','El catálogo de sistema son tablas que describen la propia base: qué tablas hay, qué columnas, de qué tipo, qué restricciones e índices. Es la base hablando de sí misma, y por eso se puede consultar con SQL corriente. En PostgreSQL vive en `information_schema` y en `pg_catalog`. No es un manual, ni un índice, ni una vista de logs.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(179,5,'json_2026',6,'Si cruzas dos tablas con LEFT JOIN, ¿qué sucede con los registros huérfanos de la tabla izquierda?','`LEFT JOIN` conserva **todas** las filas de la tabla izquierda, tengan pareja o no; las que no la tienen aparecen igual y las columnas de la derecha se rellenan con `NULL`. Ésa es justamente la diferencia con `INNER JOIN`, que las descartaría. De ahí sale un uso muy común: `LEFT JOIN` más `WHERE derecha.id IS NULL` es la forma de encontrar los huérfanos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(180,5,'json_2026',7,'¿Cuál es el propósito principal de utilizar una subconsulta correlacionada?','Una subconsulta correlacionada menciona una columna de la consulta externa, así que no se puede resolver sola: se evalúa una vez por cada fila de la principal. Eso la hace potente y también cara. La (a) describe la subconsulta **no** correlacionada, que se calcula una sola vez y es el par con el que se contrasta. Cuando el costo pesa, muchas se pueden reescribir como un `JOIN`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(181,5,'json_2026',8,'¿Qué tipo de JOIN retorna únicamente los registros que tienen coincidencias en ambas tablas?','`INNER JOIN` devuelve solo las filas con coincidencia en las dos tablas. Las otras tres existen y hacen otra cosa: `FULL OUTER JOIN` trae todo de ambos lados rellenando con `NULL`, `RIGHT OUTER JOIN` conserva todo el lado derecho, y `CROSS JOIN` combina cada fila con cada fila sin condición. Es el join por omisión: escribir solo `JOIN` significa `INNER JOIN`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(182,5,'json_2026',9,'En una consulta SELECT, ¿cuál es el orden lógico interno de evaluación del motor SQL?','El orden lógico es `FROM`, `WHERE`, `GROUP BY`, `HAVING`, `SELECT` —y `ORDER BY` al final—, que no es el orden en que se escribe. Entenderlo explica dos cosas que se preguntan siempre: por qué `WHERE` no puede filtrar por una función agregada, porque el agrupamiento todavía no ocurrió, y por qué en muchos motores no se puede usar en `WHERE` un alias definido en el `SELECT`, que se evalúa después.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(183,5,'json_2026',10,'¿Qué operador SQL permite evaluar si un valor específico está dentro del resultado de una subconsulta?','`IN` comprueba si un valor está entre los que devuelve la subconsulta: `WHERE id IN (SELECT ...)`. `EXISTS` es el distractor fuerte porque también se usa con subconsultas, pero pregunta otra cosa —si la subconsulta devuelve **alguna** fila, sin mirar qué valor—. `BETWEEN` compara contra un rango y `LIKE` contra un patrón de texto; ninguno de los dos toma un conjunto de resultados.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(184,5,'json_2026',11,'Si usas GROUP BY, ¿qué restricción impone el estándar SQL sobre las columnas del SELECT?','Toda columna del `SELECT` tiene que estar en el `GROUP BY` o venir envuelta en una función agregada como `COUNT`, `SUM` o `MAX`. El motivo es que el resultado tiene una fila por grupo, y una columna que no cumple eso tendría varios valores posibles y ninguna regla para elegir. Las otras tres inventan límites que no existen: ni el tipo, ni la cantidad de columnas, ni los alias están restringidos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(185,5,'json_2026',12,'¿Qué operador lógico utilizarías para buscar patrones de texto específicos ignorando mayúsculas?','En PostgreSQL, `ILIKE` compara patrones ignorando mayúsculas; el equivalente portátil es forzar los dos lados con `UPPER()` o `LOWER()`. `LIKE` a secas sí distingue mayúsculas de minúsculas, y ésa es la diferencia que la pregunta busca. Los otros tres nombres no existen en SQL. Ojo con una consecuencia práctica: envolver la columna en `UPPER()` suele impedir que el motor use el índice.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(186,5,'json_2026',13,'¿Qué sentencia DML permite insertar filas directamente a partir de una consulta a otra tabla?','`INSERT INTO destino SELECT ... FROM origen` inserta en una tabla **que ya existe** las filas que devuelve la consulta. La (b), `CREATE TABLE ... AS`, también copia datos pero crea la tabla en el mismo acto, así que responde a otra necesidad. `MERGE` existe en varios motores y sirve para insertar o actualizar según haya coincidencia; `UPDATE ... FROM` actualiza, no inserta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(187,5,'json_2026',14,'Al ejecutar un DELETE sin cláusula WHERE, ¿qué impacto ocurre internamente en la base de datos?','`DELETE` sin `WHERE` borra todas las filas, pero las borra **una a una y dejando registro de cada una** en el log de transacciones, de modo que la operación se puede deshacer con `ROLLBACK`. Por eso es lenta en tablas grandes y por eso existe `TRUNCATE`, que es el contraste directo. No borra la tabla —eso es `DROP`— ni reinicia los identificadores, y ningún motor la bloquea por seguridad.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(188,5,'json_2026',15,'¿Qué función principal asume una "secuencia" en el proceso de inserción de datos?','Una secuencia es un generador de números que entrega valores distintos a cada llamada, pensado para alimentar claves primarias sin que dos sesiones simultáneas obtengan el mismo. En PostgreSQL es lo que hay detrás de `SERIAL` y de las columnas `GENERATED ... AS IDENTITY`. Conviene saber que sus valores no se devuelven al deshacer una transacción: un `ROLLBACK` deja huecos en la numeración, y eso es correcto.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(189,5,'json_2026',16,'¿Qué sucede si una sentencia UPDATE viola una restricción de llave foránea (integridad referencial)?','La sentencia falla entera y no se aplica ninguna de sus modificaciones: una restricción de integridad referencial no es una advertencia, es una condición. Las otras tres describen comportamientos que ningún motor tiene: no rellena con `NULL` por su cuenta, no pide confirmación, y desde luego no desactiva la restricción para poder seguir. Si la sentencia iba dentro de una transacción, ésta queda para deshacer.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(190,5,'json_2026',17,'¿Qué propiedad ACID garantiza que una transacción fallida no deje registros parciales guardados?','La atomicidad es el todo o nada: una transacción se aplica entera o no deja rastro, así que un fallo a mitad no puede dejar registros parciales. Las otras tres son propiedades reales de ACID con otro oficio: la consistencia mantiene válidas las reglas de la base, el aislamiento evita que las transacciones simultáneas se estorben, y la durabilidad garantiza que lo confirmado sobreviva a una caída.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(191,5,'json_2026',18,'¿Qué comando asegura la persistencia permanente de los datos tras un bloque de sentencias DML?','`COMMIT` cierra la transacción y hace permanentes sus cambios; hasta ese momento nada de lo hecho es definitivo y un `ROLLBACK` lo desharía. Las otras tres existen y ninguna confirma nada. `SAVEPOINT` marca un punto intermedio al que se puede volver **dentro** de la transacción, sin cerrarla. `CHECKPOINT` es el distractor que separa: fuerza la escritura a disco de los buffers pendientes, así que suena a «persistencia permanente», pero no tiene nada que ver con confirmar una transacción — la durabilidad de lo confirmado la garantiza el registro de transacciones desde el `COMMIT`, sin esperar a ningún volcado. `FLUSH PRIVILEGES` es de MySQL y recarga permisos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(192,5,'json_2026',19,'¿Qué problema de concurrencia grave evita el máximo nivel de aislamiento (Serializable)?','El nivel `SERIALIZABLE` es el más alto y evita los tres fenómenos clásicos: lecturas sucias —ver cambios no confirmados—, lecturas no repetibles —leer dos veces y obtener distinto— y lecturas fantasma —que aparezcan filas nuevas entre dos lecturas—. El precio es menos concurrencia, porque el motor tiene que serializar el acceso. Los niveles más bajos van permitiendo uno u otro a cambio de velocidad.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(193,5,'json_2026',20,'¿Qué efecto tiene el modo AUTOCOMMIT si se encuentra activado por defecto en la consola SQL?','Con AUTOCOMMIT activo, cada sentencia que termina bien se confirma sola, como si llevara su propio `COMMIT` detrás. La consecuencia práctica es la que importa: **ya no hay nada que deshacer**, porque no queda transacción abierta. Por eso, para agrupar varias sentencias en una unidad, hay que abrir la transacción explícitamente con `BEGIN`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(194,5,'json_2026',21,'Si ejecutas ROLLBACK tras haber modificado 1000 filas sin hacer COMMIT, ¿qué pasa?','Se deshacen las 1000. `ROLLBACK` devuelve la base al estado en que estaba al empezar la transacción, sin límite de filas y sin distinguir entre inserciones, actualizaciones y borrados. Eso es la atomicidad en acción. Las otras tres inventan límites que no existen: ni un tope de 500, ni un modo de recuperación, ni un trato distinto según el tipo de sentencia.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(195,5,'json_2026',22,'¿Qué comando DDL vacía los datos de una tabla sin registrar cada fila en el log de transacciones?','`TRUNCATE TABLE` vacía la tabla de una vez, sin escribir una entrada por fila en el log, y por eso es mucho más rápido que `DELETE` en tablas grandes. Conserva la estructura: la tabla sigue existiendo, vacía. Los otros tres comandos no existen. Conviene saber que suele reiniciar las secuencias asociadas si se le pide `RESTART IDENTITY`, cosa que `DELETE` nunca hace.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(196,5,'json_2026',23,'En la creación de tablas, ¿qué restricción impide tajantemente ingresar valores repetidos?','`PRIMARY KEY` y `UNIQUE` son las que impiden valores repetidos; la diferencia entre ambas es que la primaria además no admite nulos y solo puede haber una por tabla. `NOT NULL` obliga a que haya un valor pero no a que sea distinto; `CHECK` valida una condición sobre el valor; y `FOREIGN KEY` exige que el valor exista en otra tabla, que es lo contrario de impedir repeticiones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(197,5,'json_2026',24,'¿Qué instrucción DDL se utiliza convencionalmente para modificar el tipo de dato de una columna?','La forma estándar es `ALTER TABLE tabla ALTER COLUMN columna TYPE nuevo_tipo`, y es la que usa PostgreSQL. Las otras tres no existen: `UPDATE` cambia datos y no estructura, que es la confusión que la (b) busca provocar. Ojo con algo que se pregunta poco y duele mucho: cambiar el tipo de una columna con datos dentro puede fallar si alguno no se puede convertir.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(198,5,'json_2026',26,'¿Qué diferencia técnica crítica existe entre el comando DROP TABLE y TRUNCATE TABLE?','`DROP TABLE` borra la tabla entera —datos, estructura, índices y metadatos—, y después de ejecutarlo la tabla ya no existe. `TRUNCATE TABLE` borra solo las filas y deja la tabla vacía y lista para recibir datos. La (d) invierte la clasificación: los dos son DDL, no uno de cada tipo. Y ninguno admite `WHERE`: para borrar con condición está `DELETE`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(199,5,'json_2026',27,'Al agregar una restricción NOT NULL a una columna ya existente, ¿qué precondición debe cumplirse?','La columna no puede tener ningún `NULL` en las filas existentes: la restricción se valida contra los datos que ya están, y si alguno la incumple, la sentencia falla. La salida habitual es llenar esos huecos primero con un `UPDATE` y recién después agregar la restricción. Las otras tres inventan requisitos que no existen: ni ser llave foránea, ni estar indexada, ni el estado de los registros importan.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(200,5,'json_2026',28,'¿Qué palabra reservada se emplea para asignar un valor fijo automático si este se omite al insertar?','`DEFAULT` fija el valor que toma la columna cuando la inserción no la menciona. Se declara al crear la tabla y evita tener que repetir el mismo valor en cada `INSERT`. Los otros tres nombres no existen. Conviene distinguirlo de `NOT NULL`: `DEFAULT` da un valor cuando falta, `NOT NULL` prohíbe que falte; juntos garantizan que la columna siempre tenga algo con sentido.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(201,5,'json_2026',29,'En el modelo conceptual, ¿cómo se representa idealmente la capacidad de abstracción de un problema?','El modelo conceptual se dibuja como un diagrama Entidad-Relación: entidades, sus atributos, las relaciones entre ellas y las cardinalidades. Es deliberadamente independiente del motor y hasta de si al final se usará una base relacional. Las otras tres saltan a la implementación —clases, DDL, XML—, que es justo lo que el modelo conceptual evita para poder discutirse con quien no programa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(202,5,'json_2026',30,'¿Qué característica define esencialmente a una "Entidad Fuerte" en el modelamiento conceptual?','Una entidad fuerte existe por sí sola y se identifica con sus propios atributos, sin depender de otra. Su contraste es la entidad débil, que es la (b) y que necesita de una entidad dueña para existir e identificarse. Las otras dos describen cosas que no definen la fuerza de una entidad: ni los atributos compuestos ni las llaves foráneas tienen que ver con eso.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(203,5,'json_2026',31,'¿Cómo se resuelve una relación "Muchos a Muchos" (N:M) al transformar al modelo relacional?','Una relación N:M no se puede representar con una llave foránea en ninguno de los dos lados, porque cada fila admitiría un solo valor. Se resuelve creando una **tabla intermedia** cuyas filas son los pares, con las llaves foráneas de las dos entidades formando su clave. Además de resolver el problema, esa tabla es el sitio natural para los atributos que pertenecen a la relación y no a las entidades.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(204,5,'json_2026',32,'¿Qué condición principal exige la Primera Forma Normal (1FN) al aplicarla en una tabla relacional?','La Primera Forma Normal pide que cada celda contenga un valor **atómico**: nada de listas, ni campos con varios datos separados por comas, ni grupos repetidos de columnas como `telefono1`, `telefono2`. Es la condición que hace posibles las demás: sin valores atómicos no se puede hablar de dependencias funcionales. La (b) describe justamente lo que la Tercera Forma Normal viene a eliminar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(205,5,'json_2026',33,'¿Qué tipo de dependencia se busca erradicar para alcanzar la Tercera Forma Normal (3FN)?','La Tercera Forma Normal elimina las **dependencias transitivas**: un atributo no clave que depende de otro atributo no clave en vez de depender de la clave. El caso de manual es guardar `codigo_ciudad` y `nombre_ciudad` en la tabla de personas — el nombre depende del código, no de la persona, y por eso se repite y se puede contradecir. La (a) describe lo que resuelve la Segunda Forma Normal.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(206,5,'json_2026',34,'¿Qué concepto representa fundamentalmente la cardinalidad en un modelo Entidad-Relación (MER)?','La cardinalidad dice cuántas ocurrencias de una entidad pueden vincularse con una de la otra: uno a uno, uno a muchos, muchos a muchos. Es lo que decide cómo se traduce la relación al modelo relacional — dónde va la llave foránea, o si hace falta una tabla intermedia. No tiene nada que ver con el tamaño en bytes, ni con tipos de dato, ni con el número de columnas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(207,5,'json_2026',35,'¿Por qué razón técnica de arquitectura podría llegar a justificarse una desnormalización de datos?','Se desnormaliza para que ciertas consultas dejen de pagar el costo de muchos `JOIN`, duplicando a propósito datos que la normalización había separado. Es una decisión de rendimiento, tomada a sabiendas y con una contrapartida clara: vuelven las anomalías de actualización y hay que mantener la copia. Por eso se hace después de medir, no por adelantado, y nunca para ahorrar espacio — de hecho ocupa más.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(208,5,'json_2026',36,'¿Qué herramienta o documento consolida los metadatos y definiciones del modelo de base de datos?','El diccionario de datos reúne las definiciones formales del modelo: qué tablas hay, qué columnas, de qué tipo, con qué restricciones y qué significa cada una. Es la referencia que permite entender la base sin abrirla. Las otras tres son artefactos reales del motor con otro oficio: el plan de ejecución explica una consulta, el log registra transacciones, y un volcado es una copia.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(209,5,'json_2026',37,'Al transformar una entidad débil al modelo relacional, ¿cómo se compone su llave primaria final?','La clave de una entidad débil se forma **uniendo la clave de la entidad fuerte de la que depende con su propio atributo discriminante**, porque por sí sola no distingue sus ocurrencias. Es lo que traduce al modelo relacional la dependencia de existencia: la fila no puede existir sin su dueña, y el motor lo hace cumplir con la llave foránea que forma parte de esa clave compuesta.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(210,5,'json_2026',38,'¿Cuál es el objetivo técnico primordial al aplicar el proceso de normalización en una base de datos?','La normalización busca guardar cada dato **una sola vez**, y con eso desaparecen las anomalías de inserción, actualización y borrado — los casos en que cambiar un dato en un sitio y no en otro deja la base contradiciéndose. El precio es más tablas y más `JOIN`, que es exactamente lo que la desnormalización revierte cuando el rendimiento lo justifica. La (a) describe el intercambio al revés.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(211,5,'json_2026',39,'En el contexto de un modelo relacional estricto, ¿qué concepto matemático fundamenta a las tablas?','El modelo relacional se apoya en la teoría de conjuntos: una tabla **es** una relación matemática, un subconjunto del producto cartesiano de los dominios de sus columnas, y cada fila es una tupla. De ahí viene que el orden de las filas no signifique nada y que las operaciones —unión, intersección, diferencia, producto— tengan definición formal. Es lo que separa a SQL de manipular archivos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(212,5,'json_2026',40,'En el diseño de un modelo conceptual, ¿qué es y qué implica un atributo denominado "derivado"?','Un atributo derivado **no se guarda**: su valor se calcula cuando hace falta, a partir de otros que sí están. La edad a partir de la fecha de nacimiento es el ejemplo clásico, y muestra el motivo: guardarla obligaría a actualizarla, y quedaría mal el día que nadie lo hiciera. En el diagrama se dibuja con línea punteada, y al implementar se resuelve con una columna calculada o con una vista.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(213,5,'js_2026',1,'¿Cuál es el propósito principal del "journaling" o registro de transacciones en un RDBMS?','El registro de transacciones anota lo que se va a cambiar **antes** de cambiarlo, así que tras una caída el motor puede rehacer lo confirmado y deshacer lo que quedó a medias. Es lo que sostiene la **durabilidad** y la atomicidad de ACID, no una optimización de lectura. Las otras tres describen oficios ajenos: la velocidad de lectura la dan los índices, y el cifrado de contraseñas es cosa de la aplicación.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(214,5,'js_2026',2,'¿Qué tipo de JOIN devuelve todas las filas de la tabla izquierda y las coincidencias de la derecha?','`LEFT OUTER JOIN` —o `LEFT JOIN`, que es lo mismo— conserva todas las filas de la izquierda y agrega las coincidencias de la derecha, rellenando con `NULL` donde no las hay. `RIGHT` hace lo simétrico, `FULL` conserva los dos lados, e `INNER` se queda solo con lo que casa. La palabra `OUTER` es opcional en los tres y no cambia nada: lo que manda es el lado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(215,5,'js_2026',3,'¿Qué cláusula SQL permite filtrar los resultados resultantes de una función de agrupación como SUM()?','`HAVING` filtra **después** de agrupar, y por eso puede usar funciones agregadas: `HAVING SUM(total) > 1000`. `WHERE` filtra antes, cuando los grupos todavía no existen, así que ahí un `SUM()` no tiene sentido y el motor lo rechaza. Ésa es toda la diferencia y es de las que más se preguntan. `GROUP FILTER` no existe, y `ORDER BY` ordena, no filtra.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(216,5,'js_2026',4,'¿Qué ocurre si omites la condición de unión (ON o WHERE) al realizar una consulta a múltiples tablas?','Sin condición que las una, el motor combina **cada fila de una tabla con cada fila de la otra**: el producto cartesiano. Con dos tablas de mil filas salen un millón, y por eso el síntoma clásico es una consulta que devuelve muchísimo más de lo esperado **sin dar ningún error**, que es lo que la vuelve peligrosa. Conviene saber que esto ocurre con la sintaxis de coma —`FROM a, b`— y que escribir `FROM a JOIN b` sin su `ON` es distinto: ahí el motor sí protesta. Ésa es una razón práctica para preferir siempre la sintaxis explícita con `JOIN ... ON`: convierte un olvido silencioso en un error inmediato.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(217,5,'js_2026',5,'En sentencias DML, ¿qué comando deshace los cambios no confirmados de la transacción actual en curso?','`ROLLBACK` descarta todos los cambios de la transacción en curso y deja la base como estaba al empezarla. Es la contraparte de `COMMIT` y lo que hace útil una transacción: poder equivocarse sin consecuencias mientras no se confirme. Los otros tres nombres no existen en SQL. Si hay `SAVEPOINT` declarados, se puede volver a uno de ellos en vez de deshacerlo todo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(218,5,'js_2026',6,'¿Qué comando DDL se utiliza para eliminar completamente la estructura de una tabla y sus datos?','`DROP TABLE` elimina la tabla completa: sus filas, su estructura, sus índices y sus restricciones. Después de ejecutarlo la tabla no existe y volver a usarla exige crearla de nuevo. `TRUNCATE` deja la tabla vacía pero viva, y `DELETE` borra filas con o sin condición; `DELETE TABLE` y `REMOVE TABLE` no existen. Conviene tener presente que `DROP` de una tabla referenciada por otras puede fallar por las llaves foráneas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(219,5,'js_2026',7,'¿Qué restricción DDL asegura la integridad referencial obligando a que el valor exista en otra tabla?','`FOREIGN KEY` obliga a que el valor exista en la tabla referenciada, y es lo que sostiene la integridad referencial: impide dejar filas apuntando a algo que no está. Las otras tres restringen dentro de la propia tabla — `UNIQUE` prohíbe repetidos, `PRIMARY KEY` identifica, y `CHECK` valida una condición—. Además define qué pasa al borrar o actualizar el original, con `ON DELETE CASCADE` y sus variantes.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(220,5,'js_2026',8,'A diferencia de DELETE, ¿por qué la sentencia TRUNCATE TABLE suele ser más rápida y eficiente?','`TRUNCATE` no borra fila por fila: descarta el contenido de la tabla de una vez, sin escribir una entrada por registro en el log de transacciones. Ahí está toda la diferencia de velocidad con `DELETE`. El precio es la contrapartida que hay que conocer: al no quedar registro fila a fila, no se puede deshacer con la misma facilidad, y no dispara los disparadores de borrado.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(221,5,'js_2026',9,'En el modelamiento conceptual, ¿cómo se denomina a una entidad cuya existencia depende de otra entidad?','Una entidad débil no tiene existencia propia: depende de otra para existir y para identificarse, así que su clave incluye la de la entidad fuerte. El ejemplo típico es el detalle de una factura, que no significa nada sin su factura. Los otros tres nombres suenan plausibles y no son categorías del modelo Entidad-Relación; «recursiva» describe una relación de una entidad consigo misma, que es otra cosa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(222,5,'js_2026',10,'¿Cuál es el objetivo principal de aplicar la Tercera Forma Normal (3FN) a una base de datos relacional?','La Tercera Forma Normal elimina las dependencias transitivas —atributos no clave que dependen de otros atributos no clave— y con ellas la redundancia que producen. El resultado es que cada dato vive en un solo sitio y no puede contradecirse. La (b) dice justo lo contrario de lo que ocurre: normalizar suele agregar `JOIN`, no quitarlos, y ése es el intercambio que la desnormalización revierte.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(223,5,'js_2026',11,'¿Qué elemento central documenta formalmente las tablas, atributos, tipos de datos y sus restricciones?','El diccionario de datos es el documento que formaliza qué hay en la base: tablas, atributos, tipos y restricciones, con el significado de cada uno. Sirve para que alguien entienda el modelo sin tener que deducirlo del DDL. Las otras tres son piezas reales con otro oficio: el log registra transacciones, y ni un mapa físico ni un árbol de dependencias documentan tipos ni restricciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(224,6,'json_2026',1,'¿Qué característica arquitectónica fundamental distingue al motor de Node.js?','Node corre el código JavaScript en **un solo hilo**, y no se queda esperando a las operaciones lentas: las delega y sigue atendiendo. Ésa es la combinación —un hilo, sin bloquear— que le permite sostener muchas conexiones a la vez sin crear un hilo por cada una. Las otras tres describen arquitecturas ajenas: la de un servidor tradicional con hilos bloqueantes, la de un script de navegador, y una compilación a ensamblador que no ocurre.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(225,6,'json_2026',2,'¿Qué motor interno utiliza Node.js para interpretar el código JavaScript?','Node usa V8, el mismo motor de Chrome, y por eso el JavaScript que se escribe en el servidor es el mismo lenguaje que en el navegador. Las otras tres son motores reales de otros navegadores: SpiderMonkey el de Firefox, JavaScriptCore el de Safari, y Chakra el del Edge antiguo. Lo que Node agrega por encima de V8 es todo lo que el navegador no da: archivos, red, procesos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(226,6,'json_2026',3,'¿Cuál es el rol principal de Express dentro del ecosistema de Node.js?','Express es un framework minimalista para armar servidores web: rutas, middlewares y poco más. Lo que no trae es tan importante como lo que trae — no incluye base de datos, ni ORM, ni motor de plantillas obligatorio—, y esa es su idea: dar la estructura mínima y dejar que cada proyecto elija el resto. Tampoco ejecuta nada en paralelo: hereda el modelo de un solo hilo de Node.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(227,6,'json_2026',4,'En la arquitectura de Express, ¿qué es y qué hace un "middleware"?','Un middleware es una función que se coloca en el camino de la petición y puede leerla, modificarla, responder o pasarla al siguiente con `next()`. Con eso se arman la autenticación, el registro de peticiones, el parseo del cuerpo y el manejo de errores. La clave está en ese `next()`: si un middleware no lo llama ni responde, la petición se queda colgada — y es uno de los errores más difíciles de encontrar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(228,6,'json_2026',5,'A diferencia de un servidor clásico, ¿cómo maneja Node.js las peticiones concurrentes?','Node no crea un hilo por petición: registra la operación lenta —leer un archivo, consultar la base— y sigue atendiendo, y cuando esa operación termina, su callback vuelve a la cola para ejecutarse. Por eso aguanta muchas conexiones con poca memoria. La (b) describe el modelo clásico de un hilo por usuario, que es justo lo que Node evita, y la (a) describe lo contrario de no bloquear.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(229,6,'json_2026',6,'¿Qué tipo de arquitectura de ruteo promueve fuertemente el framework Express?','Express propone declarar rutas asociando un método HTTP y una ruta a una función: `app.get(''/usuarios'', ...)`. Se lee como una tabla de lo que la aplicación ofrece, y por eso escala bien: agregar una ruta es agregar una línea, no modificar una cadena de condicionales. Las otras tres describen enfoques que Express no promueve y que se vuelven inmanejables al crecer.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(230,6,'json_2026',7,'En el ciclo de vida de un proceso Node, ¿qué detiene la ejecución del programa de forma natural?','Un proceso Node termina solo cuando no le queda nada pendiente: ni callbacks encolados, ni temporizadores activos, ni servidores escuchando. Por eso un programa que solo lee un archivo termina al acabar, y un servidor web no termina nunca — el socket abierto es trabajo pendiente permanente. Es también la explicación de un caso confuso: un `setInterval` olvidado mantiene el proceso vivo para siempre.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(231,6,'json_2026',8,'Al instalar dependencias globales con Node, ¿dónde quedan disponibles los comandos binarios?','Instalar con `-g` deja los ejecutables del paquete en un directorio que está en el `PATH` del sistema, así que se pueden invocar por su nombre desde cualquier carpeta. Una instalación local, en cambio, los deja en `node_modules/.bin`, alcanzables desde los guiones de `package.json` o con `npx`. Hoy se prefiere lo local justamente para que cada proyecto fije su versión.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(232,6,'json_2026',9,'¿Qué diferencia clave existe entre una instrucción "blocking" y "non-blocking" en Node?','Una operación bloqueante detiene el único hilo hasta terminar, y mientras tanto **ninguna otra petición se atiende**; una no bloqueante entrega el trabajo y sigue, y avisa después por un callback. En un servidor la diferencia no es de estilo: una lectura síncrona de un archivo grande deja a todos los usuarios esperando. Por eso las funciones de Node vienen casi siempre en las dos formas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(233,6,'json_2026',10,'¿Cuál es el propósito del paquete `nodemon` durante el desarrollo de una aplicación Node?','`nodemon` vigila los archivos del proyecto y reinicia el proceso cuando alguno cambia, para no tener que parar y arrancar a mano en cada edición. Es una herramienta de desarrollo y por eso va en `devDependencies`: en producción no se usa, donde el reinicio lo gestiona otra cosa. Las otras tres describen oficios de herramientas distintas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(234,6,'json_2026',11,'¿Qué objeto global en Node.js provee información y control directo sobre la ejecución actual?','`process` es el objeto global que representa al proceso en curso: da los argumentos de la línea de comandos en `process.argv`, las variables de entorno en `process.env`, el código de salida, y eventos como `exit`. Los otros tres nombres no existen. Es de los primeros que hay que conocer, porque casi toda configuración de una aplicación Node entra por `process.env`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(235,6,'json_2026',12,'¿Qué ocurre si un error no capturado (uncaught exception) alcanza la cima del Event Loop?','Un error que nadie captura llega arriba del todo y **tumba el proceso**: Node imprime la traza y sale. No hay red de seguridad por omisión, y ésa es una diferencia grande con el navegador, donde un error en un manejador no cierra la página. Por eso en producción se pone un supervisor que reinicie, y por eso conviene capturar los errores donde ocurren en vez de confiar en `process.on(''uncaughtException'')`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(236,6,'json_2026',13,'¿Qué archivo es imprescindible para que una carpeta se reconozca como proyecto Node/NPM?','`package.json` es lo que convierte una carpeta en un proyecto: declara nombre, versión, dependencias y guiones. Sin él, `npm` no sabe qué instalar ni qué ejecutar. Los otros tres son habituales pero no imprescindibles: `index.js` es una convención de nombre, `node_modules` lo genera la instalación, y un archivo de entorno es opcional y además **no se versiona**.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(237,6,'json_2026',14,'Al instalar un paquete mediante `npm install`, ¿qué carpeta almacena sus archivos físicos?','`npm install` deja los archivos de cada paquete en `node_modules`, en la raíz del proyecto. Esa carpeta se puede borrar y reconstruir en cualquier momento con otro `npm install`, y por eso **no se versiona**: lo que se versiona es `package.json` con lo declarado y `package-lock.json` con las versiones exactas. Los otros tres nombres no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(238,6,'json_2026',15,'¿Qué comando NPM inicia el asistente interactivo para crear el archivo de configuración base?','`npm init` abre el cuestionario que arma el `package.json` preguntando nombre, versión, punto de entrada y demás. La alternativa (c) es la que separa: `npm init -y` **crea el archivo igual, pero sin preguntar nada** — el `-y` acepta todos los valores por omisión, que es justo lo contrario del asistente interactivo que la pregunta pide. Es el atajo que se usa cuando el detalle da lo mismo. `npm start` ejecuta un guion ya declarado y `npm setup_project` no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(239,6,'json_2026',16,'¿Cómo se exporta correctamente un módulo personalizado en Node (CommonJS) para su reutilización?','En CommonJS lo que se exporta es lo que se asigne a `module.exports`, y con un objeto se exponen varias cosas de una vez. La (b) es la sintaxis de los módulos ES, que es el otro sistema y no se mezcla con éste en el mismo archivo — esa distinción es justamente lo que la pregunta separa. `return` no funciona fuera de una función y `expose_module()` no existe.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(240,6,'json_2026',17,'Al leer el archivo package.json, ¿qué indican los símbolos ^ o ~ en la versión de un paquete?','`^` y `~` fijan hasta dónde puede subir sola una dependencia al reinstalar: `^1.2.3` acepta cualquier `1.x.x` posterior, o sea correcciones y funciones nuevas pero no cambios que rompan; `~1.2.3` es más estricto y solo acepta `1.2.x`. Sin ningún símbolo, la versión queda clavada. Ninguna de las otras tres describe algo que esos símbolos hagan.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(241,6,'json_2026',18,'¿Qué comando NPM debes ejecutar para ver qué paquetes tienen una nueva versión disponible?','`npm outdated` lista los paquetes cuya versión instalada se quedó atrás, mostrando la actual, la que permitiría el rango declarado y la última publicada. No cambia nada: solo informa, y por eso es el paso previo a `npm update`. Los otros tres nombres no existen. Conviene mirarlo antes de actualizar, porque la columna «latest» puede estar detrás de un cambio mayor.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(242,6,'json_2026',19,'Para invocar funcionalidades de un módulo nativo o de terceros en CommonJS, ¿qué sentencia usas?','`require()` es la forma de CommonJS, el sistema de módulos con el que Node nació y el que sigue usando cuando el archivo no se declara como módulo ES. La (a), `import()`, existe en Node pero pertenece al otro sistema —y en su forma dinámica devuelve una promesa—, así que no es equivalente. Los otros dos no existen. Cuál rige lo decide la extensión del archivo y el campo `type` del `package.json`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(243,6,'json_2026',20,'¿Qué ventaja ofrece usar dependencias de desarrollo (devDependencies) en el package.json?','Las dependencias de desarrollo son las que solo hacen falta mientras se trabaja —pruebas, `nodemon`, herramientas de construcción— y se pueden dejar fuera al desplegar, con `npm install --omit=dev` o con `NODE_ENV=production`. Eso hace la instalación más liviana y reduce lo que llega al servidor. Por omisión, un `npm install` corriente sí las instala: la separación es una declaración de intención que el despliegue aprovecha.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(244,6,'json_2026',21,'¿Qué directiva de Express se utiliza habitualmente para servir contenido estático (CSS, img)?','`express.static()` es el middleware que sirve archivos tal cual están en una carpeta: hojas de estilo, imágenes, guiones del cliente. Se monta con `app.use(express.static(''public''))` y desde ahí el contenido queda disponible por su ruta. Los otros tres nombres no existen. Conviene recordar que lo que entra en esa carpeta queda público: es exactamente la decisión que en este proyecto toma `LISTA_COPIA`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(245,6,'json_2026',22,'¿Cuál es la función principal de un motor de plantillas como Handlebars en un servidor Express?','Un motor de plantillas toma un archivo con marcadores y los datos que le pasa el servidor, y produce el HTML final que se envía al navegador. Con eso la vista deja de escribirse a mano por cada caso. Las otras tres describen oficios ajenos: ni genera tablas de base de datos, ni valida formularios, ni comprime imágenes. La lógica pesada no va en la plantilla: va antes, en el controlador.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(246,6,'json_2026',24,'¿Qué concepto en Handlebars permite reutilizar bloques de código HTML, como un header o footer?','Los **partials** son fragmentos de plantilla que se escriben una vez y se incluyen donde hagan falta con `{{> nombre}}`: la cabecera, el pie, un menú. Evitan repetir el mismo HTML en cada vista y, sobre todo, evitan tener que corregirlo en diez sitios. Las otras tres opciones mezclan palabras de otros contextos y no son conceptos de Handlebars.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(247,6,'json_2026',25,'¿Qué método del objeto `res` en Express procesa una plantilla y la envía como HTML al cliente?','`res.render(''vista'', datos)` busca la plantilla, la combina con los datos y manda el HTML resultante al cliente. Es el par de `res.send()`, que envía contenido ya listo, y de `res.json()`, que envía datos. Los otros tres nombres no existen. Para que funcione hace falta haber configurado antes el motor de vistas y el directorio donde están.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(248,6,'json_2026',26,'Para que Express reconozca Handlebars como su motor base, ¿qué propiedad de `app.set` se define?','Se declara con `app.set(''view engine'', ''handlebars'')`, y junto a él suele ir `app.set(''views'', ruta)` para decir dónde están las plantillas. Con eso, `res.render(''inicio'')` ya sabe qué archivo buscar y con qué motor procesarlo. Los otros tres nombres de propiedad no existen: Express solo reconoce las suyas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(249,6,'json_2026',27,'En Handlebars, ¿qué es un "Helper" y cuál es su utilidad principal?','Un helper es una función de JavaScript que se registra en Handlebars y se puede llamar desde la plantilla, para resolver ahí lo que el lenguaje de plantillas no hace solo: formatear una fecha, comparar dos valores, pluralizar. Es la válvula de escape para lógica **de presentación**, y conviene que se quede en eso: la lógica de negocio pertenece al controlador, no a la vista.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(250,6,'json_2026',29,'Para leer el contenido de un archivo de texto de forma síncrona en Node, ¿qué método usarías?','`fs.readFileSync(ruta, ''utf8'')` lee el archivo y devuelve su contenido de una vez, deteniendo el hilo hasta terminar. Los otros tres nombres no existen. El sufijo `Sync` es la convención de Node para las versiones bloqueantes, y por eso conviene reservarlas para guiones y arranque: dentro de un servidor que atiende peticiones, cada una de ellas deja a todos los demás esperando.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(251,6,'json_2026',30,'Al leer un archivo JSON plano con `fs`, el resultado es texto crudo. ¿Cómo lo conviertes a objeto?','`JSON.parse()` convierte el texto leído en un objeto de JavaScript. Su par es `JSON.stringify()`, que es la (c) y hace el camino contrario — se confunden por parecido y por costumbre. Conviene envolverlo en `try/catch`: si el archivo está a medias o corrupto, `JSON.parse()` lanza, y sin capturar ese error el proceso se cae.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(252,6,'json_2026',31,'¿Por qué el uso exclusivo de `fs.writeFileSync()` puede ser contraproducente en aplicaciones web?','Escribir de forma síncrona detiene el único hilo hasta que el disco responde, y mientras tanto **ninguna otra petición se atiende**. En un guion que corre y termina no importa; en un servidor con usuarios, sí. La salida es la versión con promesas, `fs.promises.writeFile()`, que delega la espera y deja el hilo libre. Las otras tres describen limitaciones que `fs` no tiene.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(253,6,'json_2026',32,'Si deseas actualizar un registro dentro de un archivo JSON plano, ¿cuál es el flujo lógico correcto?','El flujo es leer el archivo, convertirlo a objeto con `JSON.parse()`, modificar lo que corresponda, volverlo a texto con `JSON.stringify()` y reescribirlo entero. Un archivo JSON no se edita por partes: se reemplaza. De ahí sale su límite como forma de persistencia — dos escrituras a la vez pueden pisarse—, que es justamente el motivo por el que el módulo siguiente pasa a una base de datos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(254,6,'json_2026',33,'Al modularizar la persistencia en archivos planos, ¿cuál es una buena práctica de diseño de código?','Conviene reunir las funciones que tocan archivos en un módulo propio y exportarlas, de modo que las rutas solo las llamen. Así la ruta habla de HTTP y el módulo habla de persistencia, y el día que los datos se muden a una base solo cambia un archivo. Las otras tres describen prácticas que atan la aplicación a su forma actual o que dejan pasar los errores en silencio.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(255,6,'json_2026',34,'¿Qué ocurre si intentas usar `fs.writeFileSync()` sobre un archivo físico que aún no existe?','Lo crea. `fs.writeFileSync()` crea el archivo si no existe y lo **sobrescribe entero** si existe, que es la parte que conviene tener presente: no agrega al final. Para eso está `fs.appendFileSync()` o abrirlo con la bandera `''a''`. Las otras tres describen comportamientos que no ocurren: no lanza `FileNotFoundError`, no ignora la orden y no pide permisos por consola.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(256,6,'json_2026',35,'¿Cómo pasas parámetros por línea de comandos al iniciar una aplicación mediante `node index.js`?','Los argumentos se escriben después del nombre del archivo, y la forma `--clave=valor` es la convención habitual porque las bibliotecas que los interpretan la reconocen sola. Las otras tres inventan sintaxis de otros contextos. Lo que llegue queda disponible en `process.argv`, que es la pregunta siguiente, y de ahí lo toman herramientas como `yargs`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(257,6,'json_2026',36,'¿Dentro de qué estructura array de Node se alojan los argumentos pasados por la línea de comandos?','`process.argv` es un arreglo donde los dos primeros elementos son fijos —la ruta de Node y la del archivo— y **a partir del tercero vienen los argumentos de verdad**. Por eso casi siempre se lo recorta con `process.argv.slice(2)`, que es el detalle que más se olvida. Los otros tres nombres no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(258,6,'json_2026',37,'¿Qué dependencia de terceros se usa comúnmente en Node para parsear fácilmente los argumentos CLI?','`yargs` interpreta los argumentos de la línea de comandos y además permite declarar cuáles son obligatorios, de qué tipo, y generar la ayuda sola. Evita tener que recorrer `process.argv` a mano. Las otras tres son bibliotecas reales con otro oficio: `nodemon` reinicia, `morgan` registra las peticiones HTTP, y `underscore` trae utilidades para colecciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(259,6,'json_2026',38,'Si una aplicación Node lanza un error y arroja un "Stack Trace", ¿qué te indica esta lectura?','La traza muestra la cadena de llamadas que llevó al error, de la más reciente hacia atrás, con archivo y línea de cada una. Se lee **de arriba abajo**: la primera línea es donde reventó, y las de abajo cuentan cómo se llegó ahí. Es la información más útil de un fallo, y conviene mirar la primera línea que apunte a código propio y no a `node_modules`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(260,6,'json_2026',39,'¿Qué atajo de teclado detiene la ejecución activa de un servidor Node.js corriendo en la terminal?','`Ctrl + C` envía la señal de interrupción al proceso en primer plano y lo detiene. Es la forma estándar en cualquier terminal. Node permite además atenderla con `process.on(''SIGINT'', ...)` para cerrar ordenadamente lo que esté abierto, que es lo que hace un servidor bien terminado antes de salir. Las otras tres no detienen un proceso de Node en la terminal.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(261,6,'json_2026',40,'¿Cuál es el comando estándar para imprimir y evaluar el valor de variables en la consola de comandos?','`console.log()` imprime en la salida estándar y sirve tanto en Node como en el navegador. Los otros tres no existen — `document.write` sí existe pero pertenece al navegador y no a Node, donde no hay documento. Conviene conocer también `console.error()`, que escribe en la salida de errores y por eso se puede separar del resto al redirigir.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(262,6,'js_2026',1,'¿Cuál es el comportamiento nativo principal del Event Loop en la arquitectura de un proceso Node.js?','El bucle de eventos es lo que permite atender muchas peticiones concurrentes con **un solo hilo**: mientras una espera por el disco o la red, el hilo atiende otra, y los callbacks de lo que va terminando se van ejecutando por turno. La (a) describe el modelo de un hilo por petición, que es justo el que Node evita, y la (b) le quita lo que lo hace útil.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(263,6,'js_2026',2,'¿Qué patrón estructural fundamental define a un middleware dentro del ciclo de vida de Express?','Un middleware es una función que se interpone entre la petición y el controlador, con acceso a la petición, la respuesta y a `next()`. Ese patrón de cadena es lo que permite componer autenticación, registro y parseo sin tocar cada ruta. Las otras tres describen piezas que no son middlewares. El orden en que se declaran importa: se ejecutan en el orden en que se registraron.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(264,6,'js_2026',3,'¿Qué herramienta detiene y reinicia automáticamente un proceso Node.js al detectar cambios en el código?','`nodemon` vigila los archivos y reinicia el proceso al detectar un cambio, que es lo que evita parar y arrancar a mano en cada edición. Las otras tres son reales y hacen otra cosa: `morgan` registra las peticiones HTTP, `express-generator` crea el esqueleto de un proyecto una sola vez, y `yargs` interpreta argumentos de la consola.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(265,6,'js_2026',4,'¿Qué comando NPM instala una dependencia asegurando que no se actualice su versión mayor accidentalmente?','`npm install <paquete> --save-exact` guarda la versión **sin** `^` ni `~`, de modo que quede clavada tal cual. Los otros tres no existen. Conviene precisar el alcance, porque es más de lo que el enunciado dice: `--save-exact` impide **cualquier** actualización automática, no solo la de versión mayor. La que permite correcciones y funciones nuevas pero bloquea los cambios que rompen es `^`, y es la que npm pone por omisión.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(266,6,'js_2026',5,'¿Dónde registra NPM por defecto la metainformación y versiones de los paquetes instalados localmente?','`package.json` es donde npm declara las dependencias del proyecto con su rango de versiones. Los otros tres no cumplen ese papel. Conviene distinguirlo de `package-lock.json`, que es su compañero y guarda la versión **exacta** que se instaló de cada paquete y de sus dependencias: el primero dice qué se acepta, el segundo qué se puso, y los dos se versionan.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(267,6,'js_2026',6,'En Handlebars, ¿qué sintaxis permite renderizar una variable escapando automáticamente el código HTML?','`{{variable}}` escapa el HTML: si el valor trae `<script>`, se muestra como texto en vez de ejecutarse. La (a), `{{{variable}}}` con tres llaves, lo inserta **sin escapar**, y por eso es la puerta de entrada de los ataques XSS cuando el dato viene de fuera. Las otras dos son de otros motores. Esa diferencia entre dos y tres llaves es de las que más se preguntan, y con razón.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(268,6,'js_2026',7,'¿Qué ventaja arquitectónica ofrece el uso de "partials" al construir vistas con motores de plantillas?','Un partial se escribe una vez y se incluye en todas las vistas que lo necesiten, así que la cabecera o el pie dejan de estar repetidos en diez archivos. La ventaja real no es escribir menos sino **corregir en un solo sitio**: un cambio en el menú se aplica en toda la aplicación. Las otras tres atribuyen a los partials cosas que no hacen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(269,6,'js_2026',8,'¿Qué elemento de Handlebars permite ejecutar lógica personalizada para procesar datos antes de renderizarlos?','Los helpers son funciones de JavaScript registradas en el motor de plantillas y llamadas desde la vista, para resolver ahí lo que la plantilla no puede sola: formatear, comparar, elegir. Los otros tres son conceptos reales de otras capas — los middlewares y los routers pertenecen a Express, y los partials reutilizan HTML pero no ejecutan lógica.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(270,6,'js_2026',9,'¿Qué módulo nativo de Node.js es indispensable para leer y escribir objetos JSON en archivos del sistema?','`fs` es el módulo nativo que da acceso al sistema de archivos: leer, escribir, comprobar si algo existe, recorrer directorios. Los otros tres también son nativos y tienen otro oficio: `path` arma y descompone rutas sin preocuparse del sistema operativo, `http` levanta servidores y hace peticiones, y `os` informa de la máquina.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(271,6,'js_2026',10,'¿Qué operación crítica debes realizar antes de guardar un objeto JavaScript en un archivo de texto plano?','Hay que convertirlo a texto con `JSON.stringify()`, porque un archivo de texto guarda caracteres y no objetos. Se le puede pasar un tercer argumento para que salga con sangría y se pueda leer a ojo: `JSON.stringify(obj, null, 2)`. Y conviene recordar lo que descarta por el camino: las funciones y las propiedades cuyo valor es `undefined` no viajan.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(272,6,'js_2026',11,'Al leer un archivo plano con JSON.parse(), ¿qué riesgo principal existe si el archivo está corrupto?','Lanza una excepción, y como es una operación **síncrona**, si nadie la captura el proceso se cae. Por eso `JSON.parse()` casi siempre va dentro de un `try/catch`, sobre todo cuando el archivo lo escribió otro programa o quedó a medias por una caída. Las otras tres describen comportamientos que no ocurren: no borra nada, no devuelve `null` en silencio y no inyecta nada.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(273,6,'js_2026',12,'¿Qué utilidad tiene el paquete "yargs" al levantar una aplicación Node.js desde la consola de comandos?','`yargs` toma los argumentos de la consola y los entrega ya interpretados, y permite declarar cuáles son obligatorios, de qué tipo son y qué valor toman por omisión, además de generar la ayuda. Es la diferencia entre leer `process.argv` a mano y tener una interfaz de línea de comandos que avisa cuando el usuario se equivoca. Las otras tres describen cosas que no hace.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(274,6,'js_2026',13,'¿Qué técnica ayuda a diferenciar niveles de error en la salida de consola al depurar una app Node.js?','Dar color y formato a la salida permite distinguir de un vistazo un aviso de un error en medio de muchas líneas. Hay bibliotecas dedicadas a eso, y también registradores que ya traen niveles —`info`, `warn`, `error`— y que además permiten apagar los mensajes de depuración en producción sin borrarlos del código. Las otras tres opciones no ayudan a depurar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(275,6,'js_2026',14,'Al depurar código asíncrono, ¿por qué los errores en un callback pueden no detener la app principal?','Porque el callback se ejecuta **después**, en otro turno del bucle de eventos, cuando la función que lo registró ya terminó. Por eso un `try/catch` puesto alrededor de la llamada asíncrona no lo alcanza: cuando el error ocurre, ese bloque hace rato que se cerró. Conviene reconciliarlo con lo que dice la pregunta sobre errores no capturados: si el error se **lanza** y nadie lo atiende, el proceso igual se cae; lo que puede pasar inadvertido es el error que llega como primer argumento del callback —el `err` del patrón error-first— y que el código sencillamente no mira.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(276,7,'json_2026',1,'¿Qué ventaja principal ofrece implementar un "pool" de conexiones en PostgreSQL con Node.js?','Abrir una conexión a PostgreSQL es caro: hay autenticación, negociación y reserva de recursos del lado del servidor. Un pool mantiene un puñado abiertas y las va prestando, así que cada consulta se ahorra ese costo. Las otras tres prometen cosas que el pool no hace: no cifra —de eso se encarga TLS—, no bloquea nada, y no duplica datos en memoria.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(277,7,'json_2026',2,'Al usar el paquete `pg`, ¿qué clase gestiona múltiples clientes conectados concurrentemente?','`Pool` es la clase de `pg` que administra el conjunto de conexiones y las reparte entre quienes las piden. Su hermana es `Client`, que representa **una** conexión y se usa cuando de verdad hace falta una sola, como en un guion suelto. Los otros tres nombres no existen. En un servidor web casi siempre se quiere `Pool`, y creado una vez al arrancar, no por petición.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(278,7,'json_2026',3,'¿Qué sucede si el "pool" de PostgreSQL alcanza su límite máximo de conexiones concurrentes?','Cuando todas las conexiones están ocupadas, las peticiones nuevas **esperan en cola** hasta que alguna se libere. No falla ni descarta: espera. Eso tiene una consecuencia práctica que conviene entender — si alguien no devuelve un cliente, la cola crece y la aplicación se va poniendo lenta antes de dar ningún error, que es el síntoma más difícil de diagnosticar.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(279,7,'json_2026',4,'En el paquete `pg`, ¿qué método libera explícitamente un cliente de vuelta al pool tras su uso?','`client.release()` devuelve el cliente al pool para que otro lo use. No cierra la conexión: la deja disponible, que es justamente el sentido del pool. La (c), `client.close()`, no existe en esa forma, y `disconnect()` tampoco. Lo habitual es llamarlo en un bloque `finally`, para que se ejecute tanto si la consulta salió bien como si lanzó.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(280,7,'json_2026',5,'¿Cuál es el riesgo de no liberar un cliente devuelto por `pool.connect()` tras usarlo?','El cliente no devuelto queda ocupado para siempre, y repetido unas cuantas veces agota el pool: las peticiones nuevas se quedan esperando en una cola que ya no avanza. La aplicación no se cae — **se cuelga**, que es peor de diagnosticar porque no hay error que leer. Por eso el `release()` va en un `finally` y no al final del camino feliz.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(281,7,'json_2026',6,'Al configurar un Pool, ¿qué parámetro define el tiempo máximo de inactividad de una conexión?','`idleTimeoutMillis` dice cuánto puede estar una conexión sin usarse antes de que el pool la cierre, para no mantener abiertas conexiones que nadie ocupa. Los otros tres nombres no existen en `pg`. Se suele configurar junto a `max` —cuántas conexiones como mucho— y `connectionTimeoutMillis`, que es cuánto espera quien pide una antes de rendirse.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(282,7,'json_2026',7,'¿Qué técnica nativa en `pg` previene eficazmente ataques de inyección SQL (SQL Injection)?','Las consultas parametrizadas mandan la sentencia y los valores **por separado**, así que el motor nunca interpreta el dato como parte del SQL. Eso corta la inyección de raíz, y no por filtrar lo que llega sino porque el valor jamás llega a ser código. Las otras tres son medidas de otra capa o directamente falsas: validar con expresiones regulares es una carrera que se pierde.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(283,7,'json_2026',8,'En una consulta parametrizada con `pg`, ¿cómo se referencian los valores dinámicos en el texto?','PostgreSQL usa marcadores posicionales numerados: `SELECT * FROM alumno WHERE id = $1`. La (a) describe la convención de MySQL y SQLite, y la (d) la de Oracle y algunos ORM — son reales pero de otros motores, y por eso son buenos distractores. La (b) es justamente lo que **no** hay que hacer: interpolar es concatenar con otro nombre.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(284,7,'json_2026',9,'¿Qué objeto JavaScript se debe pasar como argumento para ejecutar una consulta parametrizada?','Los valores van en un arreglo, en el mismo orden que los marcadores: `client.query(texto, [id, nombre])`, donde `$1` toma el primer elemento y `$2` el segundo. Por eso importa el orden y no el nombre. Si la cantidad no coincide con los marcadores, PostgreSQL rechaza la consulta antes de ejecutarla, que es la pregunta del `DELETE` sin parámetro.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(285,7,'json_2026',10,'¿Cuál es el propósito principal de usar cursores al consultar la base de datos PostgreSQL?','Un cursor permite ir trayendo el resultado **por lotes** en vez de cargarlo entero en memoria. Con una tabla de millones de filas, `client.query()` intentaría materializar todo y el proceso se quedaría sin memoria. Las otras tres describen cosas que el cursor no hace: no cifra, no agrupa en una transacción y no convierte a JSON.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(286,7,'json_2026',11,'Usando el paquete `pg-cursor`, ¿qué método extrae un bloque específico de filas del cursor?','`cursor.read(cantidad, callback)` pide el siguiente bloque de filas y las entrega al callback; cuando ya no quedan, devuelve un arreglo vacío, y ésa es la señal de que se terminó. Los otros tres nombres no existen. El patrón habitual es leer en bucle hasta ese arreglo vacío, procesando cada lote y soltándolo antes de pedir el siguiente.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(287,7,'json_2026',12,'¿Qué propiedad del objeto resultado de `query()` contiene las filas retornadas por PostgreSQL?','`result.rows` es el arreglo con las filas devueltas, cada una como un objeto cuyas claves son los nombres de las columnas. Los otros tres nombres no existen en `pg`. Junto a él viajan `result.rowCount` —cuántas filas— y `result.fields`, con la descripción de las columnas. Con un `SELECT` que no encuentra nada, `rows` es un arreglo **vacío**, no `null`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(288,7,'json_2026',13,'Si usas `async/await` para una consulta SQL, ¿cómo manejas correctamente los fallos del motor?','Con `async/await`, una consulta que falla lanza como cualquier excepción, así que se atrapa con `try/catch`. Es lo mismo que se vio en el módulo anterior y aquí se vuelve crítico: sin capturar, el error se lleva por delante el `release()` del cliente y la transacción abierta, si la hay. Por eso el patrón completo lleva `try`, `catch` con `ROLLBACK` y `finally` con `release()`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(289,7,'json_2026',14,'En mitigación de inyección SQL, ¿por qué es inseguro armar sentencias concatenando variables?','Porque el valor que llega del usuario pasa a formar parte del texto de la sentencia, y si contiene SQL, ese SQL se ejecuta. Con eso se pueden leer tablas ajenas, borrar datos o saltarse una autenticación. Las otras tres inventan límites técnicos que no existen. La solución no es escapar comillas a mano: es no concatenar, y usar parámetros.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(290,7,'json_2026',15,'Al realizar un INSERT con `pg`, ¿qué cláusula SQL adicional devuelve el registro recién creado?','`RETURNING *` hace que el `INSERT` devuelva la fila tal como quedó, incluidos los valores que puso la base —el `id` de la secuencia, las columnas con `DEFAULT`, la marca de tiempo—. Se puede pedir todo con `*` o solo algunas columnas: `RETURNING id`. Las otras tres son de otros motores o no existen: `OUTPUT INSERTED` es de SQL Server.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(291,7,'json_2026',16,'¿Qué propiedad del resultado de una consulta indica cuántos registros fueron alterados por DML?','`result.rowCount` dice cuántas filas afectó la sentencia, y es la forma de saber si un `UPDATE` o un `DELETE` de verdad tocó algo: un `rowCount` de cero significa que la condición no encontró nada, que no es un error pero casi siempre es una sorpresa. Los otros tres nombres pertenecen a otras bibliotecas o no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(292,7,'json_2026',17,'Al actualizar datos con UPDATE, ¿por qué es imperativo capturar y procesar errores en Node?','Un error que nadie atiende deja las cosas a medio camino: si la sentencia iba dentro de una transacción, ésa queda abierta, y una transacción abierta **mantiene sus bloqueos** hasta que alguien la cierre. Sumado a un cliente que tampoco se devuelve al pool, el resultado es una tabla bloqueada para los demás sin ningún error a la vista. Las otras tres describen mecanismos que no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(293,7,'json_2026',18,'Si envías un DELETE parametrizado sin valor en el parámetro ($1), ¿qué ocurre?','PostgreSQL rechaza la consulta antes de ejecutarla: el número de valores tiene que coincidir con el de marcadores, y si falta uno responde que se le entregaron menos parámetros de los que la sentencia requiere. **No asume nada ni ejecuta a medias**, y eso es una protección real — la (a) describe la catástrofe que ocurriría si el motor decidiera ignorar el filtro.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(294,7,'json_2026',19,'¿Cuál es el riesgo de ejecutar una instrucción UPDATE o DELETE sin una cláusula WHERE?','Sin `WHERE`, la sentencia se aplica a **todas** las filas de la tabla: un `UPDATE` las cambia todas y un `DELETE` las borra todas. No hay error ni aviso, porque es una sentencia perfectamente válida. La costumbre que salva es escribirla primero como `SELECT` con el mismo `WHERE`, mirar cuántas filas devuelve, y recién entonces cambiar el verbo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(295,7,'json_2026',20,'Al usar transacciones, si un INSERT falla en medio del proceso, ¿qué se debe hacer en el catch?','Ejecutar `ROLLBACK`, que deshace todo lo hecho desde el `BEGIN` y deja la base como estaba. Es la razón de ser de la transacción: que un fallo a mitad no deje la mitad aplicada. La (a) no existe como operación —no hay confirmaciones parciales— y las otras dos empeoran las cosas. Después del `ROLLBACK` viene el `release()` del cliente, en el `finally`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(296,7,'json_2026',21,'¿Qué comando SQL inicia explícitamente un bloque de control transaccional en PostgreSQL?','`BEGIN` abre el bloque transaccional en PostgreSQL, y desde ahí nada es definitivo hasta el `COMMIT`. La (a), `SET TRANSACTION`, existe de verdad y por eso es el distractor que separa: **no abre nada**, sino que fija las características —nivel de aislamiento, solo lectura— de la transacción en curso. `INIT` y `OPEN` no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(297,7,'json_2026',23,'En Node, ¿por qué debes usar el mismo cliente del pool durante toda la transacción?','Porque una transacción vive en **la sesión** de una conexión concreta: el `BEGIN` la abre en ese cliente, y un `COMMIT` enviado por otro cliente del pool no tiene nada que confirmar. Por eso una transacción se hace con `pool.connect()` para tomar un cliente y usarlo de principio a fin, en vez de con `pool.query()`, que puede darte una conexión distinta cada vez.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(298,7,'json_2026',24,'¿Qué comando confirma y persiste de forma definitiva los cambios de una transacción activa?','`COMMIT` cierra la transacción y hace permanentes sus cambios; hasta ese momento un `ROLLBACK` los desharía. Las otras tres existen y ninguna confirma nada, y la (b) es la que separa: `RELEASE SAVEPOINT` **elimina un punto de guardado y deja la transacción abierta**, así que quien crea que «liberar» un savepoint finaliza algo se lleva la pregunta mal. `SAVEPOINT` hace lo contrario —marca el punto— y `FLUSH` no es SQL. Conviene recordar que un `RELEASE SAVEPOINT` tampoco deshace lo hecho después del punto: eso sería `ROLLBACK TO SAVEPOINT`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(299,7,'json_2026',25,'¿Qué operación anula todos los cambios realizados desde el comando BEGIN al detectar un error?','`ROLLBACK` deshace todo lo hecho desde el `BEGIN` y devuelve la base al estado anterior, sin importar cuántas sentencias hubiera en medio. `TRUNCATE` es lo contrario de deshacer: vacía una tabla. `UNDO ALL` y `REVERT` no existen en SQL. Si hay `SAVEPOINT` declarados, se puede volver a uno de ellos en vez de deshacer la transacción entera.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(300,7,'json_2026',26,'Al culminar un COMMIT o ROLLBACK usando un cliente del pool, ¿qué acción final es obligatoria?','Liberar el cliente con `release()`. Confirmar o deshacer cierra la **transacción**, pero el cliente sigue prestado hasta que se devuelva, y un cliente que no vuelve es una conexión menos para todos los demás. Por eso el `release()` va en el `finally`: se ejecuta tanto tras el `COMMIT` como tras el `ROLLBACK`, y también si algo lanzó por el camino.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(301,7,'json_2026',27,'¿Qué es el modo "autocommit" en los motores de base de datos relacionales?','Con autocommit, cada sentencia que termina bien se confirma sola, como si llevara su propio `COMMIT` detrás. La consecuencia es la que importa: **no queda nada que deshacer**, porque no hay transacción abierta. Por eso, para agrupar varias sentencias en una unidad, hay que abrirla explícitamente con `BEGIN`. Las otras tres describen comportamientos que ningún motor tiene.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(302,7,'json_2026',28,'¿Qué problema principal busca resolver un mapeador objeto-relacional (ORM) como Sequelize?','Un ORM traduce entre dos mundos que no encajan solos: las tablas y filas de la base, y los objetos y clases del código. Con él se consultan y guardan datos escribiendo JavaScript en vez de SQL. Lo que **no** hace es eliminar la base ni ahorrar red — y conviene saber que el SQL sigue existiendo debajo, así que entenderlo sigue siendo necesario cuando algo va lento.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(303,7,'json_2026',29,'En la arquitectura de Sequelize, ¿qué representa el concepto lógico de "Modelo"?','Un modelo es la clase que representa una tabla: define sus columnas y sus tipos, y ofrece los métodos para consultarla y modificarla. Es la pieza central de Sequelize — todo lo demás cuelga de ahí. Las otras tres pertenecen a otras capas de la aplicación: rutas, middlewares y vistas, que no tienen nada que ver con el mapeo.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(304,7,'json_2026',30,'En Sequelize, ¿qué método de modelo se utiliza convencionalmente para insertar un nuevo registro?','`Model.create({...})` construye la instancia y la guarda en un solo paso, devolviendo el registro ya creado con el `id` que asignó la base. La (b), `Model.save()`, no existe como método de la clase — `save()` es de la **instancia**, y se usa junto a `build()` cuando se quiere crear en memoria primero y guardar después. Los otros dos no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(305,7,'json_2026',31,'Para recuperar múltiples registros desde la base de datos con Sequelize, ¿qué método se utiliza?','`Model.findAll()` devuelve un arreglo con todos los registros que cumplan las condiciones que se le pasen, y sin condiciones devuelve la tabla entera. Los otros tres nombres no existen. Sus hermanos habituales son `findOne()`, que devuelve uno solo o `null`, y `findByPk()`, que busca por clave primaria — y conviene distinguirlos porque devuelven cosas distintas.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(306,7,'json_2026',32,'¿Qué método en Sequelize se emplea para realizar la actualización (UPDATE) de registros?','`Model.update({campos}, {where})` actualiza los registros que cumplan la condición. Los otros tres nombres no existen. Ojo con el detalle que sorprende: lleva **dos** objetos, el de los valores nuevos y el de las condiciones, y olvidar el segundo actualiza toda la tabla — es el mismo peligro del `UPDATE` sin `WHERE`, con otra sintaxis.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(307,7,'json_2026',33,'¿Qué instrucción en Sequelize elimina (DELETE) físicamente un registro basado en condiciones?','`Model.destroy({where})` borra los registros que cumplan la condición. El nombre desconcierta al principio, porque no se parece a `DELETE` ni a `remove`, y por eso los otros tres distractores son tentadores; ninguno existe. `Model.drop()` tampoco es eso: `drop` en Sequelize elimina **la tabla**, que es otra cosa y bastante más grave.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(308,7,'json_2026',34,'Al definir un modelo en Sequelize, ¿qué propiedad define el tipo de dato nativo de una columna?','Cada columna se declara con un objeto que lleva `type`, y el tipo sale de `DataTypes`: `DataTypes.STRING`, `DataTypes.INTEGER`, `DataTypes.DATE`. Esa capa existe para que el mismo modelo sirva con motores distintos, que traducen cada tipo al suyo. Los otros tres nombres no existen. Junto a `type` suelen ir `allowNull`, `defaultValue` y `unique`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(309,7,'json_2026',35,'En Sequelize, ¿qué función vincula un modelo "A" con un modelo "B" en relación Uno a Uno?','`A.hasOne(B)` declara que A tiene un B, y hace que la llave foránea quede en **B** — la tabla del lado que «pertenece». Esa es la parte que más se confunde: el método se escribe en el modelo dueño, pero la columna aparece en el otro. Los otros tres nombres no existen; `belongsToOne` suena razonable y no es de Sequelize.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(310,7,'json_2026',36,'Para completar la asociación inversa "Uno a Uno" o "Uno a Muchos", ¿qué método aplica el hijo?','`belongsTo()` es el lado inverso, el que declara el hijo: `B.belongsTo(A)` completa lo que `A.hasOne(B)` o `A.hasMany(B)` empezaron, y es el que pone la llave foránea en B. Declarar los dos lados es lo que permite navegar la relación en ambos sentidos al consultar. Los otros tres nombres no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(311,7,'json_2026',38,'¿Qué requiere estrictamente una relación "Muchos a Muchos" (N:M) en bases de datos relacionales?','Una relación N:M necesita una tabla intermedia cuyas filas son los pares, con las llaves foráneas de las dos tablas. No hay forma de representarla con una columna en cualquiera de los dos lados, porque cada fila admitiría un solo valor. Esa tabla es además el sitio natural de los atributos que pertenecen a la relación y no a las entidades.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(312,7,'json_2026',39,'En Sequelize, ¿qué método establece una relación Muchos a Muchos indicando la tabla intermedia?','`A.belongsToMany(B, { through: ''AB'' })`, y hay que declararlo en los dos modelos para poder navegar en ambos sentidos. La opción `through` es obligatoria y dice qué tabla intermedia usar — puede ser un nombre o un modelo propio, y conviene lo segundo cuando la relación tiene datos suyos. Los otros tres nombres no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(313,7,'json_2026',40,'Al consultar modelos asociados en Sequelize, ¿qué parámetro se usa para cargar relaciones (JOIN)?','`include` es la opción que trae de una vez los modelos asociados, traduciéndose a un `JOIN`: `Model.findAll({ include: Otro })`. Sin ella, cada relación exigiría una consulta aparte, que es el problema de las N+1 consultas. La (d), `populate`, es real pero de Mongoose, el ORM de MongoDB, y por eso es el mejor distractor de los tres.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(314,7,'js_2026',1,'¿Qué sucede internamente al invocar client.release() tras usar una conexión de un Pool con ''pg''?','`release()` devuelve la conexión al pool y la deja disponible para la siguiente petición; **no la cierra**. Ésa es la distinción que la pregunta busca: cerrar sería tirar a la basura justo lo que el pool existe para conservar. Las otras tres describen efectos que no ocurren — no cierra transacciones ni borra cachés, y por eso conviene terminarlas uno mismo antes de soltar el cliente.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(315,7,'js_2026',2,'En Node, ¿cuándo es imperativo utilizar cursores en lugar de consultas tradicionales (client.query)?','Cuando el conjunto de resultados no cabe cómodamente en memoria. `client.query()` trae todo de una vez y construye el arreglo completo; con millones de filas, el proceso se queda sin memoria. El cursor los va entregando por lotes. Las otras tres describen situaciones donde el cursor no aporta nada: insertar, ejecutar DDL o usar transacciones.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(316,7,'js_2026',3,'¿Qué ventaja ofrece usar async/await frente a callbacks al realizar múltiples consultas consecutivas?','`async/await` deja el código asíncrono con la forma del síncrono: una consulta debajo de la otra, en vertical, en vez de anidadas dentro de callbacks. Eso importa especialmente aquí, donde una operación encadena varias consultas y el manejo de errores vuelve a ser un `try/catch` corriente. Lo que **no** hace es acelerar nada: la espera es la misma.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(317,7,'js_2026',4,'Usando ''pg'', ¿cómo se obtiene el ID generado automáticamente tras un INSERT en PostgreSQL?','Agregando `RETURNING id` —o `RETURNING *`— al `INSERT`, y leyendo después `result.rows[0].id`. Es la forma de PostgreSQL, y tiene una ventaja sobre las de otros motores: viene en la misma consulta, así que no hay una segunda llamada donde otra sesión pueda colarse. La (d) describe una propiedad de MySQL, y las otras dos no existen.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(318,7,'js_2026',5,'En el objeto Result devuelto por un UPDATE o DELETE, ¿qué propiedad indica las filas afectadas?','`Result.rowCount` dice cuántas filas afectó la sentencia. Los otros tres nombres pertenecen a otras bibliotecas o no existen. Conviene mirarlo siempre después de un `UPDATE` o un `DELETE`: si vale cero, la condición no encontró nada, y eso rara vez es lo que uno esperaba — es la diferencia entre «se hizo» y «no falló».',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(319,7,'js_2026',6,'Si ocurre un error en la tercera consulta de una transacción, ¿qué instrucción debe ejecutarse?','`ROLLBACK`, que deshace las tres consultas y no solo la que falló. En eso consiste la atomicidad: la transacción se aplica entera o no deja rastro. Las otras tres no existen como instrucciones. Y después del `ROLLBACK` queda una cosa más por hacer, que es devolver el cliente al pool con `release()`.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(320,7,'js_2026',7,'¿Qué representa principalmente un "Modelo" dentro del ecosistema del ORM Sequelize?','Un modelo es la abstracción de una tabla: define sus columnas y ofrece los métodos para operar con ella usando objetos en vez de SQL. Las otras tres describen piezas reales de una aplicación —la conexión, un middleware, una vista— que no son el modelo. La conexión, en particular, es lo que se le pasa a Sequelize al arrancar, no lo que el modelo representa.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(321,7,'js_2026',8,'En Sequelize, ¿qué método define el lado "1" de una relación uno a muchos (1:N)?','`hasMany()` se declara en el lado «uno»: `Autor.hasMany(Libro)` dice que un autor tiene muchos libros, y la llave foránea queda en la tabla de libros. Su par es `belongsTo()`, que se declara en el lado «muchos» y completa la relación. `hasOne()` es para uno a uno y `belongsToMany()` para muchos a muchos.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(322,7,'js_2026',9,'Para crear una relación N:M en Sequelize, ¿qué parámetro adicional es obligatorio en la asociación?','La opción `through`, que nombra la tabla intermedia donde viven las dos llaves foráneas. Es obligatoria porque sin ella Sequelize no sabría dónde guardar los pares. Las otras tres describen cosas que no hacen falta: ni índices agrupados, ni hooks, ni claves compuestas declaradas a mano — de la clave de la tabla intermedia se encarga Sequelize.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
INSERT INTO "pregunta" ("id","modulo","origen","numero_origen","enunciado","justificacion","dificultad","orden_fijo","estado","motivo_retiro","retirada_en","reemplazada_por","creada_en","fecha_modificacion") VALUES(323,7,'js_2026',10,'Al realizar lecturas en Sequelize, ¿qué opción permite incluir objetos de modelos relacionados (Joins)?','`include` trae los modelos asociados en la misma consulta, traduciéndose a un `JOIN`. Sin ella hay que consultar cada relación aparte, que es el problema clásico de las N+1 consultas: una para la lista y una más por cada elemento. La (a) y la (d) no existen, y `populate` —que no aparece aquí— sería la de Mongoose, no la de Sequelize.',NULL,0,'activa',NULL,NULL,NULL,'2026-09-10',NULL);
